INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0009', '特殊疑问句 What''s this/that? 询问“这是什么/那是什么”，回答 It''s a/an + 名词', '特殊疑问句 What''s this/that? 询问“这是什么/那是什么”，回答 It''s a/an + 名词', '["What''s this? It''s a book."]', '外研版', '三年级', '上册', 'Unit 2', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0009');
