INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0084', 'should + 动词原形表应该', 'should + 动词原形表应该', '["You should wear a coat and a scarf."]', '外研版', '四年级', '下册', 'Unit 6', NULL, 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0084');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0085', 'What is...looking for? 寻找', 'What is...looking for? 寻找', '["What is Lingling looking for?"]', '外研版', '四年级', '下册', 'Unit 6', NULL, 3 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0085');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0086', 'What is the weather like? 询问天气', 'What is the weather like? 询问天气', '["What is the weather like? It''s hot."]', '外研版', '四年级', '下册', 'Unit 6', NULL, 4 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0086');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0087', '祈使句：肯定形式以动词原形开头；否定形式以Don''t+动词原形开头', '祈使句：肯定形式以动词原形开头；否定形式以Don''t+动词原形开头', '["Open the window. / Don''t touch the hot water. Don''t eat quickly."]', '外研版', '五年级', '上册', 'Unit 1', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0087');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0088', 'should表示建议：You should+动词原形+其他；否定式shouldn''t=should not', 'should表示建议：You should+动词原形+其他；否定式shouldn''t=should not', '["You should have some vegetables. / You shouldn''t eat too much chocolate."]', '外研版', '五年级', '上册', 'Unit 1', NULL, 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0088');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0089', '询问饮食习惯：What do you eat+三餐? I eat+食物.；第三人称用What does+主语+eat+三餐?', '询问饮食习惯：What do you eat+三餐? I eat+食物.；第三人称用What does+主语+eat+三餐?', '["What do you eat for lunch? I eat noodles and meat. / What does Tom eat for breakfast? He eats bread and milk."]', '外研版', '五年级', '上册', 'Unit 1', NULL, 3 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0089');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0090', '祈使句的用法（肯定式和否定式）：肯定式动词原形开头；否定式Don''t+动词原形', '祈使句的用法（肯定式和否定式）：肯定式动词原形开头；否定式Don''t+动词原形', '["Plant trees in the park. / Don''t throw it away."]', '外研版', '五年级', '上册', 'Unit 2', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0090');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0091', '三个R原则：Recycle（回收利用）/ Reuse（再使用）/ Reduce（减少使用）', '三个R原则：Recycle（回收利用）/ Reuse（再使用）/ Reduce（减少使用）', '["Recycle milk cartons. / Reuse the box as a toy house. / Reduce plastic use."]', '外研版', '五年级', '上册', 'Unit 2', NULL, 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0091');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0092', '询问环保行动：What can we do to...? 回答We can+动词原形；How do we...? 回答具体步骤', '询问环保行动：What can we do to...? 回答We can+动词原形；How do we...? 回答具体步骤', '["What can we do to reduce plastic? We can use reusable bags."]', '外研版', '五年级', '上册', 'Unit 2', NULL, 3 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0092');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0093', '介绍节日日期：Earth Day comes on+日期；People+动词原形+活动', '介绍节日日期：Earth Day comes on+日期；People+动词原形+活动', '["Earth Day comes on 22 April every year."]', '外研版', '五年级', '上册', 'Unit 2', NULL, 4 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0093');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0094', '连词and：连接并列的单词、短语或句子，表示并列/顺承关系', '连词and：连接并列的单词、短语或句子，表示并列/顺承关系', '["Tutu and Duoduo are friends. / We read books and play games."]', '外研版', '五年级', '上册', 'Unit 3', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0094');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0095', '连词because：表示原因，引导原因状语从句', '连词because：表示原因，引导原因状语从句', '["He is funny because he often makes me laugh."]', '外研版', '五年级', '上册', 'Unit 3', NULL, 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0095');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0096', '连词but：表示转折关系，连接前后意思相反或对比的内容', '连词but：表示转折关系，连接前后意思相反或对比的内容', '["I have new friends, but you''re still my friend."]', '外研版', '五年级', '上册', 'Unit 3', NULL, 3 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0096');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0097', '谈论朋友异同：用the same/different/similar描述朋友间的共同点和不同点', '谈论朋友异同：用the same/different/similar描述朋友间的共同点和不同点', '["We live in the same street. / We have different hobbies."]', '外研版', '五年级', '上册', 'Unit 3', NULL, 4 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0097');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0098', '一般将来时be going to结构：主语+am/is/are+going to+动词原形，表示计划或打算做某事', '一般将来时be going to结构：主语+am/is/are+going to+动词原形，表示计划或打算做某事', '["I''m going to work hard. / She''s going to read more books. / They''re going to exercise more."]', '外研版', '五年级', '上册', 'Unit 4', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0098');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0099', 'be going to也可表示即将发生的事', 'be going to也可表示即将发生的事', '["We''re going to have the test tomorrow. / Our school''s going to have a basketball team."]', '外研版', '五年级', '上册', 'Unit 4', NULL, 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0099');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0100', '一般将来时will+动词原形：主语+will+动词原形+其他，描述未来可能发生的事情或计划', '一般将来时will+动词原形：主语+will+动词原形+其他，描述未来可能发生的事情或计划', '["People will live on the moon. / Robots will cook for us."]', '外研版', '五年级', '上册', 'Unit 5', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0100');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0101', 'will的一般疑问句：Will+主语+动词原形？肯定回答Yes, 主语will. 否定回答No, 主语won''t.', 'will的一般疑问句：Will+主语+动词原形？肯定回答Yes, 主语will. 否定回答No, 主语won''t.', '["Will it do homework? No, it won''t."]', '外研版', '五年级', '上册', 'Unit 5', NULL, 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0101');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0102', '一般现在时谈论节日习俗：主语+动词原形/动词第三人称单数+其他，表示经常发生的节日活动', '一般现在时谈论节日习俗：主语+动词原形/动词第三人称单数+其他，表示经常发生的节日活动', '["People eat mooncakes at Mid-Autumn Festival. / He visits his grandparents every Spring Festival."]', '外研版', '五年级', '上册', 'Unit 6', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0102');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0103', '一般将来时谈论节日计划：will+动词原形表示未来会发生的事；be going to+动词原形表示计划或打算', '一般将来时谈论节日计划：will+动词原形表示未来会发生的事；be going to+动词原形表示计划或打算', '["We will have a party tonight. / I''m going to make mooncakes."]', '外研版', '五年级', '上册', 'Unit 6', NULL, 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0103');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0104', '询问节日活动：What do you do at...? 问节日习俗；What are you going to do for...? 问节日计划', '询问节日活动：What do you do at...? 问节日习俗；What are you going to do for...? 问节日计划', '["What do you do at the Spring Festival? / What are you going to do for Mid-Autumn Festival?"]', '外研版', '五年级', '上册', 'Unit 6', NULL, 3 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0104');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0105', 'be动词一般过去式：am/is的过去式为was（单数主语），are的过去式为were（复数/第二人称主语）；否定形式为wasn''t/weren''t。', 'be动词一般过去式：am/is的过去式为was（单数主语），are的过去式为were（复数/第二人称主语）；否定形式为wasn''t/weren''t。', '["I was four. They were at the summer camp yesterday."]', '外研版', '五年级', '下册', 'Unit 1', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0105');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0106', '情态动词could的过去式用法：could是can的过去式，后接动词原形；否定形式为couldn''t。', '情态动词could的过去式用法：could是can的过去式，后接动词原形；否定形式为couldn''t。', '["We could play football together. She couldn''t ride a bike before."]', '外研版', '五年级', '下册', 'Unit 1', NULL, 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0106');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0107', '实义动词过去式：规则动词加-ed（clap→clapped, cook→cooked, practice→practiced, play→played, help→helped）；不规则动词需特殊记忆（learn→learnt, grow→grew, win→won, make→made, read→read）。', '实义动词过去式：规则动词加-ed（clap→clapped, cook→cooked, practice→practiced, play→played, help→helped）；不规则动词需特殊记忆（learn→learnt, grow→grew, win→won, make→made, read→read）。', '["We cooked lunch for ourselves. He won the race yesterday."]', '外研版', '五年级', '下册', 'Unit 1', NULL, 3 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0107');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0108', '时间逻辑短语At first...By the end of...：At first接过去初期状态/动作，By the end of+时间/事件接过去最终变化，均用一般过去时。', '时间逻辑短语At first...By the end of...：At first接过去初期状态/动作，By the end of+时间/事件接过去最终变化，均用一般过去时。', '["At first, I was nervous. By the end of the camp, I got much better."]', '外研版', '五年级', '下册', 'Unit 1', NULL, 4 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0108');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0109', '一般过去时动词变化：规则动词加-ed（hurry→hurried, help→helped, push→pushed, clean→cleaned, hike→hiked）；不规则动词需特殊记忆（go→went, see→saw, give→gave, speak→spoke, meet→met, sit→sat, bring→brought）。', '一般过去时动词变化：规则动词加-ed（hurry→hurried, help→helped, push→pushed, clean→cleaned, hike→hiked）；不规则动词需特殊记忆（go→went, see→saw, give→gave, speak→spoke, meet→met, sit→sat, bring→brought）。', '["They hurried up to the top of the hill. He saw some cans and picked them up."]', '外研版', '五年级', '下册', 'Unit 2', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0109');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0110', '一般过去时句型结构：陈述句（主语+动词过去式+其他）；否定句（主语+didn''t+动词原形+其他）；疑问句（Did+主语+动词原形+其他？回答Yes,主语+did./No,主语+didn''t.）。', '一般过去时句型结构：陈述句（主语+动词过去式+其他）；否定句（主语+didn''t+动词原形+其他）；疑问句（Did+主语+动词原形+其他？回答Yes,主语+did./No,主语+didn''t.）。', '["Did you help the elderly cross the street? Yes, I did. / He didn''t hurry to the top."]', '外研版', '五年级', '下册', 'Unit 2', NULL, 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0110');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0111', 'help sb (to) do sth句型：主语+helped+某人+动词原形+其他，help后接的动词必须用原形（to可省略）。', 'help sb (to) do sth句型：主语+helped+某人+动词原形+其他，help后接的动词必须用原形（to可省略）。', '["She helped me carry the heavy bag. = She helped me to carry the heavy bag."]', '外研版', '五年级', '下册', 'Unit 2', NULL, 3 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0111');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0112', 'can的用法：表能力（主语+can/can''t+动词原形）；表请求/建议（Can I+动词原形...? 回答用Yes,please./No,thanks.）。could是can的过去式。', 'can的用法：表能力（主语+can/can''t+动词原形）；表请求/建议（Can I+动词原形...? 回答用Yes,please./No,thanks.）。could是can的过去式。', '["I can help you. Can I help you carry the cart?"]', '外研版', '五年级', '下册', 'Unit 2', NULL, 4 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0112');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0113', 'Did引导的一般过去时一般疑问句：Did+主语+动词原形+其他？肯定回答Yes,主语+did. 否定回答No,主语+didn''t. 第三人称单数也用Did。', 'Did引导的一般过去时一般疑问句：Did+主语+动词原形+其他？肯定回答Yes,主语+did. 否定回答No,主语+didn''t. 第三人称单数也用Did。', '["Did you like the library? Yes, I did. / Did he read the book? No, he didn''t."]', '外研版', '五年级', '下册', 'Unit 3', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0113');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0114', 'there be句型一般过去时疑问句：Were there+名词复数+地点/时间？回答Yes,there were./No,there weren''t. 单数/不可数名词用Was there...?', 'there be句型一般过去时疑问句：Were there+名词复数+地点/时间？回答Yes,there were./No,there weren''t. 单数/不可数名词用Was there...?', '["Were there many books? No, there weren''t. / Was there a library in your school before? Yes, there was."]', '外研版', '五年级', '下册', 'Unit 3', NULL, 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0114');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0115', '一般过去时陈述句：描述过去发生的动作或存在的状态，谓语动词用过去式。时间状语有yesterday, last week, when I was young, in the past等。', '一般过去时陈述句：描述过去发生的动作或存在的状态，谓语动词用过去式。时间状语有yesterday, last week, when I was young, in the past等。', '["It kept raining. They worked together. Last week, I visited the street library."]', '外研版', '五年级', '下册', 'Unit 3', NULL, 3 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0115');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0116', '并列连词not only...but also...：表示''不仅……而且……''，连接两个并列成分。', '并列连词not only...but also...：表示''不仅……而且……''，连接两个并列成分。', '["Books bring not only joy but also knowledge to children."]', '外研版', '五年级', '下册', 'Unit 3', NULL, 4 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0116');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0117', '一般过去时特殊疑问句：对动作提问用 What/How/When+did+主语+动词原形？；对状态提问用 Why/How+was/were+主语？。did后接动词原形，be动词直接用was/were。', '一般过去时特殊疑问句：对动作提问用 What/How/When+did+主语+动词原形？；对状态提问用 Why/How+was/were+主语？。did后接动词原形，be动词直接用was/were。', '["What did ancient people eat? How did dumplings come to Xinjiang?"]', '外研版', '五年级', '下册', 'Unit 4', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0117');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0118', '一般过去时肯定句：be动词用主语+was/were+表语；实义动词用主语+动词过去式。不规则变化：go→went, do→did, bring→brought, dig→dug, bury→buried, see→saw, take→took。', '一般过去时肯定句：be动词用主语+was/were+表语；实义动词用主语+动词过去式。不规则变化：go→went, do→did, bring→brought, dig→dug, bury→buried, see→saw, take→took。', '["People found mooncakes in Xinjiang. Pepys dug a hole in his garden."]', '外研版', '五年级', '下册', 'Unit 4', NULL, 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0118');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0119', '一般过去时一般疑问句：实义动词用 Did+主语+动词原形？回答Yes,...did./No,...didn''t.；be动词用 Was/Were+主语？回答Yes,...was/were.', '一般过去时一般疑问句：实义动词用 Did+主语+动词原形？回答Yes,...did./No,...didn''t.；be动词用 Was/Were+主语？回答Yes,...was/were.', '["Did people eat mooncakes in the Tang Dynasty? Yes, they did. / Was Xinjiang a trade centre? Yes, it was."]', '外研版', '五年级', '下册', 'Unit 4', NULL, 3 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0119');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0120', '实义动词过去式规则变化：直接加-ed（look→looked）；以e结尾加-d（like→liked）；辅音+y变i加-ed（study→studied）；重读闭音节双写尾字母加-ed（dig→dug）。', '实义动词过去式规则变化：直接加-ed（look→looked）；以e结尾加-d（like→liked）；辅音+y变i加-ed（study→studied）；重读闭音节双写尾字母加-ed（dig→dug）。', '["He looked at the mirror. She studied history. Pepys dug a hole."]', '外研版', '五年级', '下册', 'Unit 4', NULL, 4 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0120');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0121', '一般过去时特殊疑问句：特殊疑问词+did+主语+动词原形+其他，did为助动词后接动词原形，答句用一般过去时陈述句。', '一般过去时特殊疑问句：特殊疑问词+did+主语+动词原形+其他，did为助动词后接动词原形，答句用一般过去时陈述句。', '["What did he do? He stole many jewels. / How did she work it out?"]', '外研版', '五年级', '下册', 'Unit 5', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0121');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0122', '实义动词不规则过去式：steal→stole, find→found, come→came, take→took, dig→dug，主语任何人称形式不变。', '实义动词不规则过去式：steal→stole, find→found, come→came, take→took, dig→dug，主语任何人称形式不变。', '["He stole many jewels. They found the secret in the letter."]', '外研版', '五年级', '下册', 'Unit 5', NULL, 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0122');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0123', 'use...to...用法：use+工具+to do sth表''用……做某事''；to do放句末表目的''为了……''，后接动词原形。', 'use...to...用法：use+工具+to do sth表''用……做某事''；to do放句末表目的''为了……''，后接动词原形。', '["She used some leaves to help. We read the letter to work out the message."]', '外研版', '五年级', '下册', 'Unit 5', NULL, 3 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0123');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0124', '祈使句否定：Don''t+动词原形，构成否定祈使句，表示''禁止、不要做某事''。肯定祈使句直接以动词原形开头。', '祈使句否定：Don''t+动词原形，构成否定祈使句，表示''禁止、不要做某事''。肯定祈使句直接以动词原形开头。', '["Don''t give the letter to his wife. / Give the letter to me."]', '外研版', '五年级', '下册', 'Unit 5', NULL, 4 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0124');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0125', '一般过去时与一般现在时对比：用was/were描述过去状态，用is/are/looks描述现在状态，通过系动词时态变化体现过去与现在的对比变化。', '一般过去时与一般现在时对比：用was/were描述过去状态，用is/are/looks描述现在状态，通过系动词时态变化体现过去与现在的对比变化。', '["The streets were full of bikes 30 years ago. Now the streets are still full of bikes. They were relaxed."]', '外研版', '五年级', '下册', 'Unit 6', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0125');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0126', '实义动词过去式：规则变化（work→worked, travel→travelled, relax→relaxed）；不规则变化（leave→left, get→got, make→made, become→became, give→gave）。', '实义动词过去式：规则变化（work→worked, travel→travelled, relax→relaxed）；不规则变化（leave→left, get→got, make→made, become→became, give→gave）。', '["We left Beijing. He gave up a good life. The mountains became a green world."]', '外研版', '五年级', '下册', 'Unit 6', NULL, 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0126');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0127', '系动词时态变化：was/were用于过去，is/are/looks用于现在，后接形容词或介词短语表状态。', '系动词时态变化：was/were用于过去，is/are/looks用于现在，后接形容词或介词短语表状态。', '["It looks the same in Grandpa''s old photos. The teahouse was quiet yesterday, it is still quiet today."]', '外研版', '五年级', '下册', 'Unit 6', NULL, 3 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0127');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0128', '数词表达：million（百万），数词+million+可数名词复数（如10 million trees）。介词短语表地点/时间：in the morning, on the mountain top, on the way to school, in time for lunch。', '数词表达：million（百万），数词+million+可数名词复数（如10 million trees）。介词短语表地点/时间：in the morning, on the mountain top, on the way to school, in time for lunch。', '["Over 10 million trees. We got to Xi''an in time for lunch."]', '外研版', '五年级', '下册', 'Unit 6', NULL, 4 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0128');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0129', 'how much引导特殊疑问句询问价格：How much + is + 单数/不可数名词？回答用It''s + 价格；How much + are + 复数名词？回答用They''re + 价格。', 'how much引导特殊疑问句询问价格：How much + is + 单数/不可数名词？回答用It''s + 价格；How much + are + 复数名词？回答用They''re + 价格。', '["How much is the pen? It''s 10 yuan. / How much are the cupcakes?"]', '外研版', '六年级', '上册', 'Unit 1', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0129');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0130', '一般现在时表示经常性、习惯性的动作或状态，常与every week, always, usually等时间状语连用；第三人称单数主语动词加-s。', '一般现在时表示经常性、习惯性的动作或状态，常与every week, always, usually等时间状语连用；第三人称单数主语动词加-s。', '["Sam always spends his money. Amy always saves her money."]', '外研版', '六年级', '上册', 'Unit 1', NULL, 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0130');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0131', '动词短语：save money存钱；spend money on sth在某物上花钱；come true实现；turn...into...把……变成……。', '动词短语：save money存钱；spend money on sth在某物上花钱；come true实现；turn...into...把……变成……。', '["He wants to turn the story into a film."]', '外研版', '六年级', '上册', 'Unit 1', NULL, 3 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0131');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0132', '形容词比较级：A + be动词 + 形容词比较级 + than + B，表示A比B更……。', '形容词比较级：A + be动词 + 形容词比较级 + than + B，表示A比B更……。', '["Apples are healthier than sweet cakes. This ruler is longer than that one."]', '外研版', '六年级', '上册', 'Unit 2', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0132');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0133', '形容词比较级规则变化：一般加-er；不发音e结尾加-r；重读闭音节双写尾字母加-er；辅音+y结尾变y为i加-er；多音节词前加more。', '形容词比较级规则变化：一般加-er；不发音e结尾加-r；重读闭音节双写尾字母加-er；辅音+y结尾变y为i加-er；多音节词前加more。', '["tall→taller, nice→nicer, big→bigger, happy→happier, beautiful→more beautiful"]', '外研版', '六年级', '上册', 'Unit 2', NULL, 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0133');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0134', '提出建议用"Why not + 动词原形…?"（为什么不……呢？）；表达观点用"In my opinion, + 句子."。', '提出建议用"Why not + 动词原形…?"（为什么不……呢？）；表达观点用"In my opinion, + 句子."。', '["Why not just eat it? In my opinion, this book is very interesting."]', '外研版', '六年级', '上册', 'Unit 2', NULL, 3 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0134');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0135', '形容词最高级：主语 + be动词 + the + 形容词最高级 + 范围(in/of...)，表示三者或以上中最……的，前面必须加定冠词the。', '形容词最高级：主语 + be动词 + the + 形容词最高级 + 范围(in/of...)，表示三者或以上中最……的，前面必须加定冠词the。', '["Mount Qomolangma is the world''s highest mountain. Tom is the tallest boy in our class."]', '外研版', '六年级', '上册', 'Unit 3', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0135');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0136', '形容词最高级规则变化：一般加-est；不发音e结尾加-st；重读闭音节双写尾字母加-est；辅音+y结尾变y为i加-est；多音节词前加most。不规则：good/well→best, bad→worst, many/much→most。', '形容词最高级规则变化：一般加-est；不发音e结尾加-st；重读闭音节双写尾字母加-est；辅音+y结尾变y为i加-est；多音节词前加most。不规则：good/well→best, bad→worst, many/much→most。', '["tall→tallest, big→biggest, happy→happiest, beautiful→most beautiful"]', '外研版', '六年级', '上册', 'Unit 3', NULL, 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0136');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0137', '"one of + the + 形容词最高级 + 复数名词"表示"最……之一"；询问"有多……"用"How + 形容词 + be动词 + 主语?"。', '"one of + the + 形容词最高级 + 复数名词"表示"最……之一"；询问"有多……"用"How + 形容词 + be动词 + 主语?"。', '["Xu Xiake is one of the most famous travellers. How high is it?"]', '外研版', '六年级', '上册', 'Unit 3', NULL, 3 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0137');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0138', '现在进行时：主语 + am/is/are + 动词-ing形式，表示此时此刻正在进行的动作。', '现在进行时：主语 + am/is/are + 动词-ing形式，表示此时此刻正在进行的动作。', '["What are you doing? I''m reading a book. I''m making a watering bottle."]', '外研版', '六年级', '上册', 'Unit 4', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0138');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0139', '描述步骤用连接词First（首先）、Next（接着）、Then（然后）、Finally（最后），清晰说明做某事的先后顺序。', '描述步骤用连接词First（首先）、Next（接着）、Then（然后）、Finally（最后），清晰说明做某事的先后顺序。', '["First, wash the apples. Next, cut them into pieces. Then, put them in the blender. Finally, turn on the blender."]', '外研版', '六年级', '上册', 'Unit 4', NULL, 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0139');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0140', '动词短语：make a hole钻洞；cut off剪掉；put...in...把……放进……；turn...into...把……变成……。', '动词短语：make a hole钻洞；cut off剪掉；put...in...把……放进……；turn...into...把……变成……。', '["Make a small hole. Cut off the bottom. Make trash into treasure."]', '外研版', '六年级', '上册', 'Unit 4', NULL, 3 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0140');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0141', 'have表示"患病"：have a + 疾病名称，如have a fever发烧、have a headache头痛、have a cold感冒。', 'have表示"患病"：have a + 疾病名称，如have a fever发烧、have a headache头痛、have a cold感冒。', '["What''s the matter? I have a fever and a bad headache."]', '外研版', '六年级', '上册', 'Unit 5', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0141');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0142', '情态动词should表示"应该"，用于提出建议或劝告，后接动词原形；否定形式为shouldn''t（不应该）。', '情态动词should表示"应该"，用于提出建议或劝告，后接动词原形；否定形式为shouldn''t（不应该）。', '["You should take this medicine. You shouldn''t read in the dark. You shouldn''t eat too much junk food."]', '外研版', '六年级', '上册', 'Unit 5', NULL, 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0142');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0143', '询问某人怎么了用"What''s the matter (with sb)?"，回答用"I have a + 疾病"。', '询问某人怎么了用"What''s the matter (with sb)?"，回答用"I have a + 疾病"。', '["What''s the matter? I have a sore throat."]', '外研版', '六年级', '上册', 'Unit 5', NULL, 3 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0143');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0144', 'What引导的感叹句：结构"What + a/an + 形容词 + 可数名词单数 + 主语 + 谓语！"；或"What + 形容词 + 可数名词复数/不可数名词 + 主语 + 谓语！"。', 'What引导的感叹句：结构"What + a/an + 形容词 + 可数名词单数 + 主语 + 谓语！"；或"What + 形容词 + 可数名词复数/不可数名词 + 主语 + 谓语！"。', '["What an interesting book it is! What beautiful flowers they are!"]', '外研版', '六年级', '上册', 'Unit 6', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0144');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0145', 'How引导的感叹句："How + 形容词/副词 + 主语 + 谓语！"，how修饰形容词或副词。', 'How引导的感叹句："How + 形容词/副词 + 主语 + 谓语！"，how修饰形容词或副词。', '["How delicious the ice cream is! How fast he runs!"]', '外研版', '六年级', '上册', 'Unit 6', NULL, 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0145');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0146', '判断用what还是how：看形容词后是否紧跟名词——紧跟名词用what，否则用how。', '判断用what还是how：看形容词后是否紧跟名词——紧跟名词用what，否则用how。', '["What a cute panda!（what修饰panda） / How cute the panda is!（how修饰cute）"]', '外研版', '六年级', '上册', 'Unit 6', NULL, 3 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0146');
