INSERT INTO t_section (id, chapter_id, name, sort, grade, term, importance, content, practice, is_deleted, create_at, create_by) SELECT 'en-sec-001', 'en-ch-001', '重点语法与句型', '1', '三年级', '上册', 'key', '{"objective":"掌握Welcome的重点语法与句型","overview":"Welcome重点语法与句型同步练习","points":["be动词am用于I（我）之后：I''m = I am","特殊疑问句 What''s your name? 询问姓名，回答用 My name is… 或 I''m…","问候语与告别语：Good morning! / Goodbye! / Have a nice day!","课堂指令祈使句（动词原形开头）：Stand up! Sit down! Open/Close your book!"]}', '{"questionCount":15,"difficulty":"混合","types":["Radio","FillBlank"]}', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_section WHERE id = 'en-sec-001');
