INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-001-012', 'en-repo-001', '12', '— Nice to meet you. — ___', 'Radio', '{"id":"en-q-001-012","title":"— Nice to meet you. — ___","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Welcome","section":"重点语法与句型","knowledgePoint":["Welcome 重点句型"],"examAnalysis":"考查初次见面的礼貌用语Nice to meet you.（很高兴见到你）（Welcome句型）。对方说''很高兴见到你''，礼貌应答是Nice to meet you, too.（我也很高兴见到你）。B项Goodbye.（再见）、C项Thank you.（谢谢）、D项I''m fine.（我很好）都不是对此句的正确回应，故A正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Nice to meet you, too.","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"Goodbye.","attribute":{}},{"id":"c","title":"Thank you.","attribute":{}},{"id":"d","title":"I''m fine.","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","上册","Welcome"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Welcome', '重点语法与句型', '["Welcome 重点句型"]', 'hard', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-001-012');
