INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-001-013', 'en-repo-001', '13', '放学时和同学告别，你应该说：___', 'Radio', '{"id":"en-q-001-013","title":"放学时和同学告别，你应该说：___","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Welcome","section":"重点语法与句型","knowledgePoint":["问候语与告别语：Good morning! / Goodbye! / Have a nice day!"],"examAnalysis":"考查告别语（Welcome语法点3）。放学分别时应说Goodbye!（再见！），还可以加上Have a nice day!（祝你有美好的一天！）。B项Good morning!（早上好）是早晨问候，C项What''s your name?（你叫什么名字）是询问姓名，D项Nice to meet you.（很高兴见到你）是见面用语，均不符合告别场合，故A正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Goodbye! Have a nice day!","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"Good morning!","attribute":{}},{"id":"c","title":"What''s your name?","attribute":{}},{"id":"d","title":"Nice to meet you.","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","上册","Welcome"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Welcome', '重点语法与句型', '["问候语与告别语：Good morning! / Goodbye! / Have a nice day!"]', 'hard', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-001-013');
