INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-003-001', 'en-repo-003', '1', 'What''s this? ___ my schoolbag.（这是什么？这是我的书包。）', 'FillBlank', '{"id":"en-q-003-001","title":"What''s this? ___ my schoolbag.（这是什么？这是我的书包。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["特殊疑问句 What''s this/that? 询问“这是什么/那是什么”，回答 It''s a/an + 名词"],"examAnalysis":"考查特殊疑问句 What''s this? 的回答（Unit 2语法点1）。问“这是什么”，回答用 It''s = It is + 名词。It''s my schoolbag. 意为“这是我的书包”，句首字母大写，故填 It''s。","examCorrectAnswer":"It''s","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","上册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["特殊疑问句 What''s this/that? 询问“这是什么/那是什么”，回答 It''s a/an + 名词"]', 'medium', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-003-001');
