INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-003-002', 'en-repo-003', '2', 'What''s this? It''s ___ book.（这是什么？这是一本书。）', 'FillBlank', '{"id":"en-q-003-002","title":"What''s this? It''s ___ book.（这是什么？这是一本书。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"easy","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["不定冠词 a/an：以元音音素开头的名词前用 an，其他用 a"],"examAnalysis":"考查不定冠词 a 的用法（Unit 2语法点3）。book（书）以辅音音素开头，前面用不定冠词 a，表示“一本”。故填 a。","examCorrectAnswer":"a","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","上册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["不定冠词 a/an：以元音音素开头的名词前用 an，其他用 a"]', 'easy', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-003-002');
