INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-003-010', 'en-repo-003', '10', '— Is it a pencil? — Yes, ___.', 'Radio', '{"id":"en-q-003-010","title":"— Is it a pencil? — Yes, ___.","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["一般疑问句 Is it…? 询问物品，肯定回答 Yes, it is. 否定回答 No, it isn''t."],"examAnalysis":"考查 Is it…? 的肯定回答（Unit 2语法点2）。Is it…? 的肯定回答是 Yes, it is.，否定是 No, it isn''t.。B 项是否定回答，与 Yes 矛盾；C 项 I am 用于回答 I 的问题；D 项 it are 搭配错误，故 A 正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"it is","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"it isn''t","attribute":{}},{"id":"c","title":"I am","attribute":{}},{"id":"d","title":"it are","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","上册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["一般疑问句 Is it…? 询问物品，肯定回答 Yes, it is. 否定回答 No, it isn''t."]', 'medium', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-003-010');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-003-010', 'en-kp-003-03', 'en-q-003-010', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-003-010');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-003-011', 'en-repo-003', '11', '在 What''s that? 中，that 指的是：___', 'Radio', '{"id":"en-q-003-011","title":"在 What''s that? 中，that 指的是：___","type":"Radio","attribute":{"subject":"英语","difficulty":"easy","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["特殊疑问句 What''s this/that? 询问“这是什么/那是什么”，回答 It''s a/an + 名词"],"examAnalysis":"考查指示代词 this/that 的区别（Unit 2语法点1）。this 指近处的“这个”，that 指远处的“那个”。问句 What''s that? 是问远处“那是什么”，故选 B。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"近处的东西","attribute":{}},{"id":"b","title":"远处的东西","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"一种颜色","attribute":{}},{"id":"d","title":"一个人名","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","上册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["特殊疑问句 What''s this/that? 询问“这是什么/那是什么”，回答 It''s a/an + 名词"]', 'easy', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-003-011');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-003-011', 'en-kp-003-01', 'en-q-003-011', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-003-011');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-003-012', 'en-repo-003', '12', 'Pack my bag for school. 是祈使句，它以 ___ 开头。', 'Radio', '{"id":"en-q-003-012","title":"Pack my bag for school. 是祈使句，它以 ___ 开头。","type":"Radio","attribute":{"subject":"英语","difficulty":"easy","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["祈使句（动词原形开头，表指令/建议）：Pack my pen. Pack my bag for school."],"examAnalysis":"考查祈使句的构成（Unit 2语法点4）。祈使句表示指令或建议，以动词原形开头。本句 Pack（收拾）就是动词原形。B、C、D 都不能构成祈使句，故 A 正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"动词原形","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"名词","attribute":{}},{"id":"c","title":"颜色词","attribute":{}},{"id":"d","title":"数词","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","上册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["祈使句（动词原形开头，表指令/建议）：Pack my pen. Pack my bag for school."]', 'easy', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-003-012');
