INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-003-013', 'en-repo-003', '13', '— What''s this? — It''s ___ ruler.', 'Radio', '{"id":"en-q-003-013","title":"— What''s this? — It''s ___ ruler.","type":"Radio","attribute":{"subject":"英语","difficulty":"easy","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["不定冠词 a/an：以元音音素开头的名词前用 an，其他用 a"],"examAnalysis":"考查不定冠词 a 的用法（Unit 2语法点3）。ruler（尺子）以辅音音素 /r/ 开头，前面用 a。B 项 an 用于元音音素开头的词前；C、D 是 be 动词，此处不需要，故 A 正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"a","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"an","attribute":{}},{"id":"c","title":"is","attribute":{}},{"id":"d","title":"are","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","上册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["不定冠词 a/an：以元音音素开头的名词前用 an，其他用 a"]', 'easy', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-003-013');
