INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-003-014', 'en-repo-003', '14', '下列句子中哪一句是正确的？', 'Radio', '{"id":"en-q-003-014","title":"下列句子中哪一句是正确的？","type":"Radio","attribute":{"subject":"英语","difficulty":"easy","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["不定冠词 a/an：以元音音素开头的名词前用 an，其他用 a"],"examAnalysis":"考查不定冠词 an 与 be 动词（Unit 2语法点3）。eraser 以元音音素开头，前面用 an，且句子需要 be 动词 is。A 项 eraser 前误用 a；C 项缺 be 动词；D 项 eraser 前误用 a 且语序错误，故 B 正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"It''s a eraser.","attribute":{}},{"id":"b","title":"It''s an eraser.","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"It an eraser.","attribute":{}},{"id":"d","title":"Is it a eraser.","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","上册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["不定冠词 a/an：以元音音素开头的名词前用 an，其他用 a"]', 'easy', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-003-014');
