INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-008-008', 'en-repo-008', '8', '— Are they pandas? — Yes, ___.', 'Radio', '{"id":"en-q-008-008","title":"— Are they pandas? — Yes, ___.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["确认多个事物的名称：Are they + 可数名词复数?"],"examAnalysis":"考查 Are they...? 的肯定回答（Unit 1语法点1）。问句用 Are they 开头，肯定回答用 Yes, they are.，否定回答用 No, they aren''t.。B项 they are 正确。A项 they do 用于Do开头的问句；C项 they is 搭配错误，they后要用are；D项 it is 用于单数事物，与they不一致，故B正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"they do","attribute":{}},{"id":"b","title":"they are","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"they is","attribute":{}},{"id":"d","title":"it is","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","下册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["确认多个事物的名称：Are they + 可数名词复数?"]', 'hard', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-008-008');
