INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-008-009', 'en-repo-008', '9', '— What are they? — They are ___.', 'Radio', '{"id":"en-q-008-009","title":"— What are they? — They are ___.","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["询问多个事物名称：What are they? 答语 They are + 名词复数"],"examAnalysis":"考查 What are they? 的答语（Unit 1语法点3）。主语They是复数，后面的名词也要用复数，panda的复数是pandas。C项 pandas 正确。A、B、D项都是单数形式，与They are不搭配，故C正确。相关规则：They are 后接可数名词复数。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"panda","attribute":{}},{"id":"b","title":"a panda","attribute":{}},{"id":"c","title":"pandas","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"the panda","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","下册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["询问多个事物名称：What are they? 答语 They are + 名词复数"]', 'medium', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-008-009');
