INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-008-013', 'en-repo-008', '13', '你向朋友介绍身边的同学琳达，应该说：___', 'Radio', '{"id":"en-q-008-013","title":"你向朋友介绍身边的同学琳达，应该说：___","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["介绍某人：This is + 人名"],"examAnalysis":"考查介绍某人的句型 This is + 人名（Unit 1语法点4）。介绍身边的人用 This is + 人名。A项 This is Linda.（这是琳达）正确。B项 Are you Linda? 是问句；C项 She is fine. 意思是''她很好''；D项 Goodbye, Linda! 是告别语，都不是介绍用语，故A正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"This is Linda.","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"Are you Linda?","attribute":{}},{"id":"c","title":"She is fine.","attribute":{}},{"id":"d","title":"Goodbye, Linda!","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","下册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["介绍某人：This is + 人名"]', 'hard', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-008-013');
