INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-009-001', 'en-repo-009', '1', 'I ___ got a nose.（我有一个鼻子。）', 'FillBlank', '{"id":"en-q-009-001","title":"I ___ got a nose.（我有一个鼻子。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["描述外形特征（肯定）：主语 + have/has got (+a/an/数词)(形容词) + 身体部位"],"examAnalysis":"考查描述外形特征的肯定句型 主语 + have got + 身体部位（Unit 2语法点1）。主语是I（我），用have got，故填have。相关规则：have got 表示''有''，I/you/we/they 后面用 have got，如 I have got a nose.（我有一个鼻子。）","examCorrectAnswer":"have","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","下册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["描述外形特征（肯定）：主语 + have/has got (+a/an/数词)(形容词) + 身体部位"]', 'hard', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-009-001');
