INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-009-011', 'en-repo-009', '11', '— Have you got a pen? — No, I ___.', 'Radio', '{"id":"en-q-009-011","title":"— Have you got a pen? — No, I ___.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["描述外形特征（否定）：主语 + have/has not got ..."],"examAnalysis":"考查 have got 一般疑问句的否定回答（Unit 2语法点2）。问句用 Have you got...?，否定回答用 No, I haven''t.。C项 haven''t 正确。A项 don''t 用于Do开头的问句；B项 am not 与have不搭配；D项 hasn''t 用于第三人称单数，主语是I应用haven''t，故C正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"don''t","attribute":{}},{"id":"b","title":"am not","attribute":{}},{"id":"c","title":"haven''t","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"hasn''t","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","下册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["描述外形特征（否定）：主语 + have/has not got ..."]', 'hard', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-009-011');
