INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-010-013', 'en-repo-010', '13', '"……怎么样？"用英语说：What ___ some tea?', 'Radio', '{"id":"en-q-010-013","title":"\"……怎么样？\"用英语说：What ___ some tea?","type":"Radio","attribute":{"subject":"英语","difficulty":"easy","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["Unit 3 重点句型"],"examAnalysis":"考查提建议句型 What about...?（Unit 3重点句子）。What about + 事物? 表示''……怎么样？''，固定用about。A项正确。B、C、D项都不能与What搭配表示''……怎么样''，故A正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"about","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"is","attribute":{}},{"id":"c","title":"are","attribute":{}},{"id":"d","title":"do","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","下册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["Unit 3 重点句型"]', 'easy', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-010-013');
