INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-011-001', 'en-repo-011', '1', 'I like ___.（我喜欢唱歌。）', 'FillBlank', '{"id":"en-q-011-001","title":"I like ___.（我喜欢唱歌。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 4","section":"重点语法与句型","knowledgePoint":["表达喜欢做某事：主语 + like(s) + 动词-ing 形式 (+其他)"],"examAnalysis":"考查表达喜欢做某事 like + 动词-ing（Unit 4语法点1）。like 后面的动词要用-ing形式，sing 的-ing形式是 singing，故填singing。相关规则：like doing sth. 表示''喜欢做某事''，动词要加-ing，如 I like singing.（我喜欢唱歌。）","examCorrectAnswer":"singing","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","下册","Unit 4"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 4', '重点语法与句型', '["表达喜欢做某事：主语 + like(s) + 动词-ing 形式 (+其他)"]', 'hard', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-011-001');
