INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-011-002', 'en-repo-011', '2', 'They like ___.（他们喜欢跑步。）', 'FillBlank', '{"id":"en-q-011-002","title":"They like ___.（他们喜欢跑步。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 4","section":"重点语法与句型","knowledgePoint":["表达喜欢做某事：主语 + like(s) + 动词-ing 形式 (+其他)"],"examAnalysis":"考查 like + 动词-ing（Unit 4语法点1）。like 后接动词-ing，run 是重读闭音节，要双写末尾字母 n 再加-ing，即 running，故填running。相关规则：run → running，类似的还有 swim → swimming。","examCorrectAnswer":"running","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","下册","Unit 4"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 4', '重点语法与句型', '["表达喜欢做某事：主语 + like(s) + 动词-ing 形式 (+其他)"]', 'medium', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-011-002');
