INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-011-003', 'en-repo-011', '3', 'He likes ___.（他喜欢画画。）', 'FillBlank', '{"id":"en-q-011-003","title":"He likes ___.（他喜欢画画。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 4","section":"重点语法与句型","knowledgePoint":["表达喜欢做某事：主语 + like(s) + 动词-ing 形式 (+其他)"],"examAnalysis":"考查 like + 动词-ing，且第三人称单数用 likes（Unit 4语法点1）。He 是第三人称单数，用 likes；draw 的-ing形式是 drawing，故填drawing。相关规则：He/She likes + 动词-ing，如 He likes drawing.（他喜欢画画。）","examCorrectAnswer":"drawing","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","下册","Unit 4"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 4', '重点语法与句型', '["表达喜欢做某事：主语 + like(s) + 动词-ing 形式 (+其他)"]', 'medium', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-011-003');
