INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-011-004', 'en-repo-011', '4', '— What do you like ___? — I like doing tai chi.（— 你喜欢做什么？— 我喜欢打太极。）', 'FillBlank', '{"id":"en-q-011-004","title":"— What do you like ___? — I like doing tai chi.（— 你喜欢做什么？— 我喜欢打太极。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 4","section":"重点语法与句型","knowledgePoint":["询问对方业余爱好：What do you like doing? 答 I/We like + 动词-ing"],"examAnalysis":"考查询问对方业余爱好的句型 What do you like doing?（Unit 4语法点2）。like 后接动词-ing，''做''是do，-ing形式是 doing，故填doing。相关规则：询问''你喜欢做什么？''用 What do you like doing?，回答用 I like + 动词-ing。","examCorrectAnswer":"doing","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","下册","Unit 4"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 4', '重点语法与句型', '["询问对方业余爱好：What do you like doing? 答 I/We like + 动词-ing"]', 'hard', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-011-004');
