INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-014-006', 'en-repo-014', '6', 'Don''t ___ up! Never stop!（不要放弃！决不停下！）', 'FillBlank', '{"id":"en-q-014-006","title":"Don''t ___ up! Never stop!（不要放弃！决不停下！）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["祈使句表鼓励或命令：肯定句以动词原形开头；否定句在句首加Don''t。"],"examAnalysis":"考查否定祈使句（Unit 1语法点3）。原句出自Don''t give up! Never stop!，否定祈使句在句首加Don''t，后面接动词原形，''放弃''是give up，故填give。相关规则：祈使句肯定句以动词原形开头，否定句在句首加Don''t+动词原形。","examCorrectAnswer":"give","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["祈使句表鼓励或命令：肯定句以动词原形开头；否定句在句首加Don''t。"]', 'medium', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-014-006');
