INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-014-008', 'en-repo-014', '8', '— Dad, may I play outside? — ___', 'Radio', '{"id":"en-q-014-008","title":"— Dad, may I play outside? — ___","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["Unit 1 单元综合"],"examAnalysis":"考查May I…?请求许可的应答。题干问句虽用may，但对照本单元''Can/May I…?''类请求的回答逻辑，回答要针对''我能不能出去''作答；四个选项中只有C项Yes, I can.（是的，我能/可以）是肯定且结构正确的应答。A项用do回答情态动词问句、B项人称错（答句主语应为I而非you）、D项No与场合不符且用don''t，均排除。相关规则：请求许可类问句，答句要前后一致，肯定用Yes, I can/may.，否定用No, I can''t/may not.。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Yes, you do.","attribute":{}},{"id":"b","title":"Yes, you may.","attribute":{}},{"id":"c","title":"Yes, I can.","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"No, I don''t.","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["Unit 1 单元综合"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-014-008');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-014-008', 'en-kp-014-04', 'en-q-014-008', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-014-008');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-014-009', 'en-repo-014', '9', 'Can you ___ volleyball?', 'Radio', '{"id":"en-q-014-009","title":"Can you ___ volleyball?","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["can后面必须接动词原形，且无人称和数的变化。"],"examAnalysis":"考查can后接动词原形（Unit 1语法点2）。情态动词can后面必须接动词原形，''打排球''是play volleyball，故选A。B项plays是第三人称单数形式，C项playing是现在分词，D项to play是不定式，都不能直接跟在can后面。相关规则：can + 动词原形，无人称和数的变化。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"play","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"plays","attribute":{}},{"id":"c","title":"playing","attribute":{}},{"id":"d","title":"to play","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["can后面必须接动词原形，且无人称和数的变化。"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-014-009');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-014-009', 'en-kp-014-02', 'en-q-014-009', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-014-009');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-014-010', 'en-repo-014', '10', 'She can ___ very high.', 'Radio', '{"id":"en-q-014-010","title":"She can ___ very high.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["can后面必须接动词原形，且无人称和数的变化。"],"examAnalysis":"考查can无人称和数的变化、后接动词原形（Unit 1语法点2）。主语是She（第三人称单数），但can没有形式变化，其后仍用动词原形jump，故选C。A项jumps是一般现在时第三人称单数形式，不能用于can后；B、D项同样不能跟在can后。相关规则：can表能力时无人称变化，can+动词原形。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"jumps","attribute":{}},{"id":"b","title":"jumping","attribute":{}},{"id":"c","title":"jump","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"to jump","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["can后面必须接动词原形，且无人称和数的变化。"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-014-010');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-014-010', 'en-kp-014-02', 'en-q-014-010', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-014-010');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-014-011', 'en-repo-014', '11', '— Can you play ping-pong? — ___. But I can learn.', 'Radio', '{"id":"en-q-014-011","title":"— Can you play ping-pong? — ___. But I can learn.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["情态动词can表示\"能力、会\"：疑问句把can提到主语前，即\"Can+主语+动词原形?\"；肯定回答\"Yes, 主语+ca"],"examAnalysis":"考查can一般疑问句的否定回答（Unit 1语法点1）。后一句But I can learn.（但我可以学）说明''不会打''，是否定回答，用No, I can''t.，故选D。A项Yes与后句转折矛盾；B项用do回答情态动词问句错误；C项No后面不能接can，前后矛盾。相关规则：Can you…?否定回答为No, I can''t.","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Yes, I can.","attribute":{}},{"id":"b","title":"Yes, I do.","attribute":{}},{"id":"c","title":"No, I can.","attribute":{}},{"id":"d","title":"No, I can''t.","attribute":{"examCorrectAnswer":"d"}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["情态动词can表示\"能力、会\"：疑问句把can提到主语前，即\"Can+主语+动词原形?\"；肯定回答\"Yes, 主语+ca"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-014-011');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-014-011', 'en-kp-014-01', 'en-q-014-011', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-014-011');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-014-012', 'en-repo-014', '12', '___ give up!（不要放弃！）', 'Radio', '{"id":"en-q-014-012","title":"___ give up!（不要放弃！）","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["祈使句表鼓励或命令：肯定句以动词原形开头；否定句在句首加Don''t。"],"examAnalysis":"考查否定祈使句（Unit 1语法点3）。否定祈使句在动词原形前加Don''t，Don''t give up!意为''不要放弃！''，故选B。A项Not不能直接放在句首引导祈使句；C项Doesn''t用于第三人称单数的一般现在时否定，不用于祈使句；D项No后接名词或动名词，不能接动词原形give。相关规则：祈使句否定式 = Don''t + 动词原形。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Not","attribute":{}},{"id":"b","title":"Don''t","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"Doesn''t","attribute":{}},{"id":"d","title":"No","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["祈使句表鼓励或命令：肯定句以动词原形开头；否定句在句首加Don''t。"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-014-012');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-014-012', 'en-kp-014-03', 'en-q-014-012', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-014-012');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-014-013', 'en-repo-014', '13', '下列句子中哪一句是正确的？', 'Radio', '{"id":"en-q-014-013","title":"下列句子中哪一句是正确的？","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["can后面必须接动词原形，且无人称和数的变化。"],"examAnalysis":"考查can后接动词原形（Unit 1语法点2）。can后面必须用动词原形，C项They can run fast.中run是原形，正确。A项can后用了swims、B项用了runs、D项用了playing，都违反''can+动词原形''规则。相关规则：情态动词can无人称和数的变化，其后一律接动词原形。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"She can swims fast.","attribute":{}},{"id":"b","title":"He can runs fast.","attribute":{}},{"id":"c","title":"They can run fast.","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"I can playing ping-pong.","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["can后面必须接动词原形，且无人称和数的变化。"]', 'medium', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-014-013');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-014-013', 'en-kp-014-02', 'en-q-014-013', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-014-013');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-014-014', 'en-repo-014', '14', 'Never ___ up! You can do it!', 'Radio', '{"id":"en-q-014-014","title":"Never ___ up! You can do it!","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["祈使句表鼓励或命令：肯定句以动词原形开头；否定句在句首加Don''t。"],"examAnalysis":"考查表鼓励的祈使句（Unit 1语法点3，原句Never stop!）。Never+动词原形构成鼓励/告诫的祈使句，''放弃''是give up，故用动词原形give，选A。B、C、D项都不是动词原形，不能用于Never引导的祈使句。相关规则：祈使句以动词原形开头；Never+动词原形表示''决不……''。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"give","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"gives","attribute":{}},{"id":"c","title":"giving","attribute":{}},{"id":"d","title":"to give","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["祈使句表鼓励或命令：肯定句以动词原形开头；否定句在句首加Don''t。"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-014-014');
