INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-015-001', 'en-repo-015', '1', 'Dad, ___ I play outside?（爸爸，我可以出去玩吗？）', 'FillBlank', '{"id":"en-q-015-001","title":"Dad, ___ I play outside?（爸爸，我可以出去玩吗？）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["情态动词may表示请求许可：\"May I+动词原形…?\"意为\"我可以……吗？\"，语气委婉。"],"examAnalysis":"考查情态动词may表请求许可（Unit 2语法点1）。原句为Dad, may I play outside?，''我可以……吗？''用May I+动词原形，语气委婉，故填may。相关规则：May I…?用于礼貌请求许可，肯定回答常用Yes. / Sure.，否定用No, you can''t/may not.","examCorrectAnswer":"may","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["情态动词may表示请求许可：\"May I+动词原形…?\"意为\"我可以……吗？\"，语气委婉。"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-015-001');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-015-001', 'en-kp-015-01', 'en-q-015-001', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-015-001');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-015-002', 'en-repo-015', '2', 'But can you ___ your room first?（但是你能先整理一下你的房间吗？）', 'FillBlank', '{"id":"en-q-015-002","title":"But can you ___ your room first?（但是你能先整理一下你的房间吗？）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["请求别人帮忙用\"Can you+动词原形…?\"，意为\"你能……吗？\"。"],"examAnalysis":"考查请求帮忙的Can you…?句型及can后接动词原形（Unit 2语法点2）。原句为But can you tidy your room first?，''整理''是tidy，can后用动词原形，故填tidy。相关规则：请求别人帮忙用Can you+动词原形…?，意为''你能……吗？''。","examCorrectAnswer":"tidy","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["请求别人帮忙用\"Can you+动词原形…?\"，意为\"你能……吗？\"。"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-015-002');
