INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-016-005', 'en-repo-016', '5', 'Is it cold ___ hot?（是冷还是热？）', 'FillBlank', '{"id":"en-q-016-005","title":"Is it cold ___ hot?（是冷还是热？）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"easy","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["选择疑问句用or连接两个并列选项，不能用yes/no回答，要直接选择回答。"],"examAnalysis":"考查选择疑问句（Unit 3语法点2）。原句为Is it cold or hot?，选择疑问句用or连接两个并列选项''冷还是热''，故填or。相关规则：选择疑问句不能用Yes/No回答，要直接选其中一项回答。","examCorrectAnswer":"or","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["选择疑问句用or连接两个并列选项，不能用yes/no回答，要直接选择回答。"]', 'easy', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-016-005');
