INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-016-006', 'en-repo-016', '6', '— What''s the weather like today? — ___ sunny.（— 今天天气怎么样？— 天气晴朗。）', 'FillBlank', '{"id":"en-q-016-006","title":"— What''s the weather like today? — ___ sunny.（— 今天天气怎么样？— 天气晴朗。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["询问天气用\"What''s the weather like?\"（天气怎么样？），回答用\"It''s+描述天气的形容词.\"。"],"examAnalysis":"考查天气问句的回答（Unit 3语法点1）。What''s the weather like?的回答用It''s+形容词，''天气晴朗''是It''s sunny，故填It''s。相关规则：用It指代天气，It''s = It is，后面接sunny/cloudy等天气形容词。","examCorrectAnswer":"It''s","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["询问天气用\"What''s the weather like?\"（天气怎么样？），回答用\"It''s+描述天气的形容词.\"。"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-016-006');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-016-006', 'en-kp-016-01', 'en-q-016-006', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-016-006');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-016-007', 'en-repo-016', '7', 'Is it rainy or ___?（是下雨还是晴天？）', 'FillBlank', '{"id":"en-q-016-007","title":"Is it rainy or ___?（是下雨还是晴天？）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["选择疑问句用or连接两个并列选项，不能用yes/no回答，要直接选择回答。"],"examAnalysis":"考查选择疑问句（Unit 3语法点2）。原句为Is it rainy or sunny?，or连接rainy（下雨的）和sunny（晴朗的）两个选项，故填sunny。相关规则：or连接两个并列的天气形容词构成选择疑问句，回答要直接选一项。","examCorrectAnswer":"sunny","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["选择疑问句用or连接两个并列选项，不能用yes/no回答，要直接选择回答。"]', 'medium', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-016-007');
