INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-016-008', 'en-repo-016', '8', '— What''s the weather like? — ___', 'Radio', '{"id":"en-q-016-008","title":"— What''s the weather like? — ___","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["询问天气用\"What''s the weather like?\"（天气怎么样？），回答用\"It''s+描述天气的形容词.\"。"],"examAnalysis":"考查天气问句的回答（Unit 3语法点1）。What''s the weather like?要用It''s+形容词回答，B项It''s sunny.（天气晴朗）正确。A项Yes, it is.用于一般疑问句Is it…?的回答；C项like sunny结构不对；D项It''s sun.误用名词sun，应用形容词sunny。相关规则：回答天气用It''s+天气形容词。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Yes, it is.","attribute":{}},{"id":"b","title":"It''s sunny.","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"I like sunny.","attribute":{}},{"id":"d","title":"It''s sun.","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["询问天气用\"What''s the weather like?\"（天气怎么样？），回答用\"It''s+描述天气的形容词.\"。"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-016-008');
