INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-016-009', 'en-repo-016', '9', 'Let''s ___ out to play.', 'Radio', '{"id":"en-q-016-009","title":"Let''s ___ out to play.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["提建议用\"Let''s+动词原形\"（让我们……吧）。"],"examAnalysis":"考查Let''s+动词原形（Unit 3语法点3，原句We can go out to play.）。Let''s后接动词原形go，go out to play意为''出去玩''，故选C。A项goes是第三人称单数，B项going是现在分词，D项to go是不定式，都不能跟在Let''s后。相关规则：Let''s+动词原形，表示''让我们……吧''。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"goes","attribute":{}},{"id":"b","title":"going","attribute":{}},{"id":"c","title":"go","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"to go","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["提建议用\"Let''s+动词原形\"（让我们……吧）。"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-016-009');
