INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-016-010', 'en-repo-016', '10', '— Is it cold or hot? — ___', 'Radio', '{"id":"en-q-016-010","title":"— Is it cold or hot? — ___","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["选择疑问句用or连接两个并列选项，不能用yes/no回答，要直接选择回答。"],"examAnalysis":"考查选择疑问句的回答方式（Unit 3语法点2）。Is it cold or hot?是选择疑问句，不能用Yes/No回答，要直接选择一项，C项It''s cold.（是冷的）正确。A、B、D项都用Yes/No回答，不符合选择疑问句的应答规则。相关规则：选择疑问句用or连接，直接选择回答，不能说Yes/No。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Yes, it is.","attribute":{}},{"id":"b","title":"No, it isn''t.","attribute":{}},{"id":"c","title":"It''s cold.","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"Yes, it''s cold.","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["选择疑问句用or连接两个并列选项，不能用yes/no回答，要直接选择回答。"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-016-010');
