INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-017-003', 'en-repo-017', '3', 'I like summer best. I can ___ ice cream.（我最喜欢夏天。我可以吃冰淇淋。）', 'FillBlank', '{"id":"en-q-017-003","title":"I like summer best. I can ___ ice cream.（我最喜欢夏天。我可以吃冰淇淋。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 4","section":"重点语法与句型","knowledgePoint":["Unit 4 重点句型"],"examAnalysis":"考查can后接动词原形（Unit 4重点句子3）。原句为I can eat ice cream.，''吃''是eat，can后用动词原形，故填eat。相关规则：情态动词can后接动词原形，无人称和数的变化。","examCorrectAnswer":"eat","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 4"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 4', '重点语法与句型', '["Unit 4 重点句型"]', 'medium', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-017-003');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-017-003', 'en-kp-017-02', 'en-q-017-003', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-017-003');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-017-004', 'en-repo-017', '4', 'What ___ you, Lingling?（玲玲，你呢？）', 'FillBlank', '{"id":"en-q-017-004","title":"What ___ you, Lingling?（玲玲，你呢？）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 4","section":"重点语法与句型","knowledgePoint":["\"What about you?\"用于反问对方（……呢？），避免重复。"],"examAnalysis":"考查反问对方的句型What about you?（Unit 4语法点3）。原句为What about you, Lingling?，What about…?意为''……呢？''，用来反问对方、避免重复，故填about。相关规则：What about you? = 你呢？用于重复对方的问题反问回去。","examCorrectAnswer":"about","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 4"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 4', '重点语法与句型', '["\"What about you?\"用于反问对方（……呢？），避免重复。"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-017-004');
