INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-017-008', 'en-repo-017', '8', '— What''s your favourite season? — ___', 'Radio', '{"id":"en-q-017-008","title":"— What''s your favourite season? — ___","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 4","section":"重点语法与句型","knowledgePoint":["询问\"最喜欢……\"用\"What''s your favourite…?\"；表达\"最喜欢某事物\"用\"主语+like(s)…b"],"examAnalysis":"考查What''s your favourite…?的回答（Unit 4语法点1）。问句问''你最喜欢的季节是什么''，回答用I like…best.，B项I like summer best.（我最喜欢夏天）正确。A项Yes, I do.用于do引导的一般疑问句；C项It''s season.语义不通；D项like swimming（喜欢游泳）没有回答''最喜欢的季节''。相关规则：问最喜欢什么，答I like…best.","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Yes, I do.","attribute":{}},{"id":"b","title":"I like summer best.","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"It''s season.","attribute":{}},{"id":"d","title":"I like swimming.","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 4"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 4', '重点语法与句型', '["询问\"最喜欢……\"用\"What''s your favourite…?\"；表达\"最喜欢某事物\"用\"主语+like(s)…b"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-017-008');
