INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-017-009', 'en-repo-017', '9', '— Why do you like summer? — ___', 'Radio', '{"id":"en-q-017-009","title":"— Why do you like summer? — ___","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 4","section":"重点语法与句型","knowledgePoint":["Why引导特殊疑问句询问原因，必须用Because来回答。"],"examAnalysis":"考查Why问句用Because回答（Unit 4语法点2）。Why…?问原因，必须用Because…回答，C项Because my birthday is in summer.（因为我的生日在夏天）正确。A、B项用Yes/No回答不对，Why问句不能用Yes/No；D项It''s summer.没有回答原因。相关规则：Why问，Because答。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Yes, I like.","attribute":{}},{"id":"b","title":"No, I don''t.","attribute":{}},{"id":"c","title":"Because my birthday is in summer.","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"It''s summer.","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 4"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 4', '重点语法与句型', '["Why引导特殊疑问句询问原因，必须用Because来回答。"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-017-009');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-017-009', 'en-kp-017-04', 'en-q-017-009', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-017-009');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-017-010', 'en-repo-017', '10', 'I like autumn ___.（我最喜欢秋天。）', 'Radio', '{"id":"en-q-017-010","title":"I like autumn ___.（我最喜欢秋天。）","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 4","section":"重点语法与句型","knowledgePoint":["询问\"最喜欢……\"用\"What''s your favourite…?\"；表达\"最喜欢某事物\"用\"主语+like(s)…b"],"examAnalysis":"考查''最喜欢''用like…best（Unit 4语法点1）。like…best表示''最喜欢''，like autumn best意为''最喜欢秋天''，故选D。A项good、B项well是原级''好''，不能表示''最''；C项very是副词''非常''，不与like搭配表示最喜欢。相关规则：主语+like(s)+名词+best = 最喜欢……。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"good","attribute":{}},{"id":"b","title":"well","attribute":{}},{"id":"c","title":"very","attribute":{}},{"id":"d","title":"best","attribute":{"examCorrectAnswer":"d"}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 4"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 4', '重点语法与句型', '["询问\"最喜欢……\"用\"What''s your favourite…?\"；表达\"最喜欢某事物\"用\"主语+like(s)…b"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-017-010');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-017-010', 'en-kp-017-01', 'en-q-017-010', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-017-010');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-017-011', 'en-repo-017', '11', '— I like winter best. What about you? — ___', 'Radio', '{"id":"en-q-017-011","title":"— I like winter best. What about you? — ___","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 4","section":"重点语法与句型","knowledgePoint":["\"What about you?\"用于反问对方（……呢？），避免重复。"],"examAnalysis":"考查What about you?的应答（Unit 4语法点3）。What about you?意为''你呢？''，反问对方最喜欢什么季节，回答仍用I like…best.，B项I like summer best.正确。A项Yes, I do.是一般疑问句回答；C项No, thanks.用于拒绝；D项You''re welcome.用于道谢应答。相关规则：What about you?用来反问对方，回答要顺着话题说自己的情况。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Yes, I do.","attribute":{}},{"id":"b","title":"I like summer best.","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"No, thanks.","attribute":{}},{"id":"d","title":"You''re welcome.","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 4"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 4', '重点语法与句型', '["\"What about you?\"用于反问对方（……呢？），避免重复。"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-017-011');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-017-011', 'en-kp-017-03', 'en-q-017-011', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-017-011');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-017-012', 'en-repo-017', '12', '— ___ do you like spring? — Because I can fly kites.', 'Radio', '{"id":"en-q-017-012","title":"— ___ do you like spring? — Because I can fly kites.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 4","section":"重点语法与句型","knowledgePoint":["Why引导特殊疑问句询问原因，必须用Because来回答。"],"examAnalysis":"考查Why引导原因问句（Unit 4语法点2）。答句用Because…回答原因，问句必然用Why（为什么）提问，故选C。A项What问事物，B项Where问地点，D项When问时间，都不能用Because回答。相关规则：Why…?问原因，Because…答原因。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"What","attribute":{}},{"id":"b","title":"Where","attribute":{}},{"id":"c","title":"Why","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"When","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 4"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 4', '重点语法与句型', '["Why引导特殊疑问句询问原因，必须用Because来回答。"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-017-012');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-017-012', 'en-kp-017-04', 'en-q-017-012', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-017-012');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-017-013', 'en-repo-017', '13', '"What about you?" 在对话中用来：___', 'Radio', '{"id":"en-q-017-013","title":"\"What about you?\" 在对话中用来：___","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 4","section":"重点语法与句型","knowledgePoint":["\"What about you?\"用于反问对方（……呢？），避免重复。"],"examAnalysis":"考查What about you?的用法（Unit 4语法点3）。What about you?意为''你呢？''，用于说完自己的情况后反问对方，避免重复提问，故选C。A项道别用Goodbye；B项道谢用Thank you；D项询问天气用What''s the weather like?，均不对。相关规则：What about + 人/物? = ……呢？","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"道别","attribute":{}},{"id":"b","title":"道谢","attribute":{}},{"id":"c","title":"反问对方\"……呢\"","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"询问天气","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 4"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 4', '重点语法与句型', '["\"What about you?\"用于反问对方（……呢？），避免重复。"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-017-013');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-017-013', 'en-kp-017-03', 'en-q-017-013', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-017-013');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-017-014', 'en-repo-017', '14', 'She ___ winter best.', 'Radio', '{"id":"en-q-017-014","title":"She ___ winter best.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 4","section":"重点语法与句型","knowledgePoint":["询问\"最喜欢……\"用\"What''s your favourite…?\"；表达\"最喜欢某事物\"用\"主语+like(s)…b"],"examAnalysis":"考查like…best及一般现在时第三人称单数（Unit 4语法点1）。主语She是第三人称单数，一般现在时中动词like要加-s，变为likes，即She likes winter best.，故选A。B项like用于第一、二人称或复数主语；C项liking、D项to like不能作谓语。相关规则：主语是第三人称单数时，行为动词加-s/-es。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"likes","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"like","attribute":{}},{"id":"c","title":"liking","attribute":{}},{"id":"d","title":"to like","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 4"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 4', '重点语法与句型', '["询问\"最喜欢……\"用\"What''s your favourite…?\"；表达\"最喜欢某事物\"用\"主语+like(s)…b"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-017-014');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-017-014', 'en-kp-017-01', 'en-q-017-014', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-017-014');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-017-015', 'en-repo-017', '15', '下列句子中哪一句正确表达"我最喜欢冬天"？', 'Radio', '{"id":"en-q-017-015","title":"下列句子中哪一句正确表达\"我最喜欢冬天\"？","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 4","section":"重点语法与句型","knowledgePoint":["询问\"最喜欢……\"用\"What''s your favourite…?\"；表达\"最喜欢某事物\"用\"主语+like(s)…b"],"examAnalysis":"考查like…best的语序（Unit 4语法点1）。''最喜欢冬天''是I like winter best.，best放在句末，故选B。A项best位置错误；C项good不能表示''最''，也不放在句末；D项favourite是形容词，不能直接作动词。相关规则：like + 宾语 + best，best放句末。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"I like best winter.","attribute":{}},{"id":"b","title":"I like winter best.","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"I like winter good.","attribute":{}},{"id":"d","title":"I favourite winter.","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 4"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 4', '重点语法与句型', '["询问\"最喜欢……\"用\"What''s your favourite…?\"；表达\"最喜欢某事物\"用\"主语+like(s)…b"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-017-015');
