INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-018-002', 'en-repo-018', '2', 'Let''s go ___ car! It''s fast!（我们开车去吧！开车很快！）', 'FillBlank', '{"id":"en-q-018-002","title":"Let''s go ___ car! It''s fast!（我们开车去吧！开车很快！）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 5","section":"重点语法与句型","knowledgePoint":["表示\"乘某种交通工具\"用\"by+交通工具名词\"，中间不加冠词。"],"examAnalysis":"考查by+交通工具（Unit 5语法点2）。原句为Let''s go by car!，''乘小汽车、开车''是by car，中间不加冠词，故填by。相关规则：by+交通工具名词，中间不加a/the，如by bus、by bike。","examCorrectAnswer":"by","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 5"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 5', '重点语法与句型', '["表示\"乘某种交通工具\"用\"by+交通工具名词\"，中间不加冠词。"]', 'medium', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-018-002');
