INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-018-014', 'en-repo-018', '14', '— How do you go to school? — ___', 'Radio', '{"id":"en-q-018-014","title":"— How do you go to school? — ___","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 5","section":"重点语法与句型","knowledgePoint":["询问交通方式用\"How do/does+主语+get/go…?\"（……怎么去？）。"],"examAnalysis":"考查How问交通方式的回答（Unit 5语法点1，原句I go by bike.）。问句问''你怎么上学''，回答用by+交通工具，B项I go by bike.（我骑自行车去）正确。A项Yes, I do.是一般疑问句回答；C项I am fine.回答身体状况；D项It''s fast.答非所问。相关规则：How问出行方式，答by+交通工具。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Yes, I do.","attribute":{}},{"id":"b","title":"I go by bike.","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"I am fine.","attribute":{}},{"id":"d","title":"It''s fast.","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 5"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 5', '重点语法与句型', '["询问交通方式用\"How do/does+主语+get/go…?\"（……怎么去？）。"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-018-014');
