INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-018-015', 'en-repo-018', '15', 'He ___ by subway.', 'Radio', '{"id":"en-q-018-015","title":"He ___ by subway.","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 5","section":"重点语法与句型","knowledgePoint":["一般现在时中，主语是第三人称单数时，行为动词要加-s/-es（go→goes）。"],"examAnalysis":"考查第三人称单数动词加-es及拼写（Unit 5语法点3）。主语He是第三人称单数，go要变为goes（加-es），故选C。A项go用于非三单主语；B项gos拼写错误，go以o结尾应加-es；D项going是现在分词。相关规则：以o结尾的动词go，三单形式加-es变goes。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"go","attribute":{}},{"id":"b","title":"gos","attribute":{}},{"id":"c","title":"goes","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"going","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 5"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 5', '重点语法与句型', '["一般现在时中，主语是第三人称单数时，行为动词要加-s/-es（go→goes）。"]', 'medium', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-018-015');
