INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-019-007', 'en-kp-019-01', 'en-q-019-007', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-019-007');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-019-008', 'en-repo-019', '8', '"一直往前走"的英语是：___', 'Radio', '{"id":"en-q-019-008","title":"\"一直往前走\"的英语是：___","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 6","section":"重点语法与句型","knowledgePoint":["指路/问路用祈使句：\"Go straight on.\"（直走）、\"Turn left/right.\"（向左/右转）。"],"examAnalysis":"考查指路祈使句的含义（Unit 6语法点1）。''一直往前走、直走''是Go straight on.，故选B。A项Turn left.是''左转''，C项Turn right.是''右转''，D项Sit down.是''坐下''，都不对。相关规则：Go straight on. = 直走；Turn left/right = 左/右转。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Turn left.","attribute":{}},{"id":"b","title":"Go straight on.","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"Turn right.","attribute":{}},{"id":"d","title":"Sit down.","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 6"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 6', '重点语法与句型', '["指路/问路用祈使句：\"Go straight on.\"（直走）、\"Turn left/right.\"（向左/右转）。"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-019-008');
