INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-019-009', 'en-repo-019', '9', 'Turn right ___ the hospital.', 'Radio', '{"id":"en-q-019-009","title":"Turn right ___ the hospital.","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 6","section":"重点语法与句型","knowledgePoint":["在某个地点转弯用介词at+小地点。"],"examAnalysis":"考查在小地点转弯用介词at（Unit 6语法点2）。''在医院那里右转''是Turn right at the hospital，hospital是小地点，用at，故选C。A项on、B项in、D项to都不与小地点这样搭配指路。相关规则：at+小地点，表示在某处转弯。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"on","attribute":{}},{"id":"b","title":"in","attribute":{}},{"id":"c","title":"at","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"to","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 6"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 6', '重点语法与句型', '["在某个地点转弯用介词at+小地点。"]', 'medium', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-019-009');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-019-009', 'en-kp-019-03', 'en-q-019-009', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-019-009');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-019-010', 'en-repo-019', '10', 'She ___ left at the library.', 'Radio', '{"id":"en-q-019-010","title":"She ___ left at the library.","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 6","section":"重点语法与句型","knowledgePoint":["一般现在时表经常性动作：主语是第三人称单数，动词加-s/-es（go→goes, turn→turns）。"],"examAnalysis":"考查一般现在时第三人称单数（Unit 6语法点3）。主语She是第三人称单数，动词turn要加-s变为turns，故选D。A项turn用于非三单主语；B项turning是现在分词；C项to turn是不定式，都不能作谓语。相关规则：三单主语后动词加-s，turn→turns。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"turn","attribute":{}},{"id":"b","title":"turning","attribute":{}},{"id":"c","title":"to turn","attribute":{}},{"id":"d","title":"turns","attribute":{"examCorrectAnswer":"d"}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 6"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 6', '重点语法与句型', '["一般现在时表经常性动作：主语是第三人称单数，动词加-s/-es（go→goes, turn→turns）。"]', 'medium', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-019-010');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-019-010', 'en-kp-019-02', 'en-q-019-010', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-019-010');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-019-011', 'en-repo-019', '11', '— Where ___ she go? — She goes to the museum.', 'Radio', '{"id":"en-q-019-011","title":"— Where ___ she go? — She goes to the museum.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 6","section":"重点语法与句型","knowledgePoint":["一般现在时表经常性动作：主语是第三人称单数，动词加-s/-es（go→goes, turn→turns）。"],"examAnalysis":"考查特殊疑问句的助动词（Unit 6语法点3，原句Where does she go?）。主语She是第三人称单数，句中已有实义动词go，疑问句要加助动词does，故选C。A项do用于非三单主语；B项is、D项are是be动词，不能与实义动词原形go这样连用。相关规则：三单主语的特殊疑问句：疑问词+does+主语+动词原形。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"do","attribute":{}},{"id":"b","title":"is","attribute":{}},{"id":"c","title":"does","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"are","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 6"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 6', '重点语法与句型', '["一般现在时表经常性动作：主语是第三人称单数，动词加-s/-es（go→goes, turn→turns）。"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-019-011');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-019-011', 'en-kp-019-02', 'en-q-019-011', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-019-011');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-019-012', 'en-repo-019', '12', '"左转"的英语是：___', 'Radio', '{"id":"en-q-019-012","title":"\"左转\"的英语是：___","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 6","section":"重点语法与句型","knowledgePoint":["指路/问路用祈使句：\"Go straight on.\"（直走）、\"Turn left/right.\"（向左/右转）。"],"examAnalysis":"考查指路祈使句Turn left（Unit 6语法点1）。''左转''是Turn left.，故选D。A项Turn right.是''右转''，B项Go straight.是''直走''，C项Be careful.是''当心''，都不对。相关规则：Turn left.左转；Turn right.右转。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Turn right.","attribute":{}},{"id":"b","title":"Go straight.","attribute":{}},{"id":"c","title":"Be careful.","attribute":{}},{"id":"d","title":"Turn left.","attribute":{"examCorrectAnswer":"d"}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 6"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 6', '重点语法与句型', '["指路/问路用祈使句：\"Go straight on.\"（直走）、\"Turn left/right.\"（向左/右转）。"]', 'medium', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-019-012');
