INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-020-005', 'en-repo-020', '5', 'I want ___ be a police officer when I grow up.（我长大后想成为一名警察。）', 'FillBlank', '{"id":"en-q-020-005","title":"I want ___ be a police officer when I grow up.（我长大后想成为一名警察。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["want to be + 职业，表长大后想成为"],"examAnalysis":"考查 want to be + 职业 表''长大后想成为……''（Unit 1语法点4）。''想要成为……''用 want to be + 职业名词，want 后要接带 to 的不定式，故填 to。如 I want to be a teacher.（我想当老师）。","examCorrectAnswer":"to","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","下册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["want to be + 职业，表长大后想成为"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-020-005');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-020-005', 'en-kp-020-04', 'en-q-020-005', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-020-005');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-020-006', 'en-repo-020', '6', 'Is your uncle a ___? Yes, he drives a taxi.（你叔叔是司机吗？是的，他开出租车。）', 'FillBlank', '{"id":"en-q-020-006","title":"Is your uncle a ___? Yes, he drives a taxi.（你叔叔是司机吗？是的，他开出租车。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["Unit 1 重点句型"],"examAnalysis":"考查职业名词及一般疑问句 Is sb a…?（Unit 1句型）。由答句 he drives a taxi（他开出租车）可知叔叔的职业是''司机''driver。问句 Is your uncle a driver?（你叔叔是司机吗？）。drive（驾驶）对应的职业名词是 driver。","examCorrectAnswer":"driver","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","下册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["Unit 1 重点句型"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-020-006');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-020-006', 'en-kp-020-05', 'en-q-020-006', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-020-006');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-020-007', 'en-repo-020', '7', 'Many people work at ___. They brighten the night for others.（许多人在夜间工作，他们为别人照亮夜晚。）', 'FillBlank', '{"id":"en-q-020-007","title":"Many people work at ___. They brighten the night for others.（许多人在夜间工作，他们为别人照亮夜晚。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["Unit 1 重点句型"],"examAnalysis":"考查核心句 Many people work at night.（Unit 1重点句子）。''在夜间''是固定搭配 at night，night 意为''夜晚、夜间''。后半句 brighten the night for others（为别人照亮夜晚）也提示了 night 一词。","examCorrectAnswer":"night","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","下册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["Unit 1 重点句型"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-020-007');
