INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-020-009', 'en-repo-020', '9', 'My mother ___ in a school.', 'Radio', '{"id":"en-q-020-009","title":"My mother ___ in a school.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["一般现在时第三人称单数动词加-s"],"examAnalysis":"考查一般现在时第三人称单数动词加-s（Unit 1语法点2）。主语 My mother 是第三人称单数，动词要用三单形式 works。A项 work 是原形，只用于 I/you/we/they；C项 working 不能单独作谓语；D项 worked 是过去式，本句是描述日常工作，应用一般现在时，故B正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"worked","attribute":{}},{"id":"b","title":"working","attribute":{}},{"id":"c","title":"work","attribute":{}},{"id":"d","title":"works","attribute":{"examCorrectAnswer":"d"}}]}', 'exam', '单元练习', '["外研版","四年级","下册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["一般现在时第三人称单数动词加-s"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-020-009');
