INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-020-011', 'en-repo-020', '11', 'I want ___ when I grow up.', 'Radio', '{"id":"en-q-020-011","title":"I want ___ when I grow up.","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["want to be + 职业，表长大后想成为"],"examAnalysis":"考查 want to be + 职业（Unit 1语法点4）。''想要成为……''用 want to be + 职业名词，want 后接带 to 的不定式。A项 be 前缺 to；C项 being 是动名词，want 后不接 doing；D项 is 不能跟在 want 后，故B正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"to be a teacher","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"being a teacher","attribute":{}},{"id":"c","title":"be a teacher","attribute":{}},{"id":"d","title":"is a teacher","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","下册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["want to be + 职业，表长大后想成为"]', 'medium', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-020-011');
