INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-020-012', 'en-repo-020', '12', '下面哪个句子正确表达''你叔叔是司机吗？''？', 'Radio', '{"id":"en-q-020-012","title":"下面哪个句子正确表达''你叔叔是司机吗？''？","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["Unit 1 重点句型"],"examAnalysis":"考查询问职业的一般疑问句 Is sb a…?（Unit 1句型）。主语 your uncle 是第三人称单数，''是司机吗''应用 Is your uncle a driver?。B项 Are 与单数主语不搭配；C、D项 do/does 是助动词，后面要接动词原形，不能直接接 a driver，故A正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Are your uncle a driver?","attribute":{}},{"id":"b","title":"Do your uncle a driver?","attribute":{}},{"id":"c","title":"Does your uncle a driver?","attribute":{}},{"id":"d","title":"Is your uncle a driver?","attribute":{"examCorrectAnswer":"d"}}]}', 'exam', '单元练习', '["外研版","四年级","下册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["Unit 1 重点句型"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-020-012');
