INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-020-013', 'en-repo-020', '13', 'The nurse ___ sick people every day.', 'Radio', '{"id":"en-q-020-013","title":"The nurse ___ sick people every day.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["一般现在时第三人称单数动词加-s"],"examAnalysis":"考查一般现在时第三人称单数加-s（Unit 1语法点2）。主语 The nurse 是三单，every day 表示经常性动作，用一般现在时，动词 help→helps。B项 help 是原形；C项 helping 不能单独作谓语；D项 is help 结构错误，故A正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"help","attribute":{}},{"id":"b","title":"is help","attribute":{}},{"id":"c","title":"helping","attribute":{}},{"id":"d","title":"helps","attribute":{"examCorrectAnswer":"d"}}]}', 'exam', '单元练习', '["外研版","四年级","下册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["一般现在时第三人称单数动词加-s"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-020-013');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-020-013', 'en-kp-020-02', 'en-q-020-013', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-020-013');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-020-014', 'en-repo-020', '14', 'My grandpa works on a ___. He grows rice and vegetables. 他的职业最可能是？', 'Radio', '{"id":"en-q-020-014","title":"My grandpa works on a ___. He grows rice and vegetables. 他的职业最可能是？","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["Unit 1 重点句型"],"examAnalysis":"考查职业与工作地点的对应（Unit 1词汇与句型）。由 works on a ___（在……工作）和 grows rice and vegetables（种水稻和蔬菜）可知他是''农民''farmer，农场是 farm。A项 doctor 在医院工作；B项 teacher 在学校工作；C项 postman 送信，都与''种地''不符，故D正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"postman","attribute":{}},{"id":"b","title":"teacher","attribute":{}},{"id":"c","title":"doctor","attribute":{}},{"id":"d","title":"farmer","attribute":{"examCorrectAnswer":"d"}}]}', 'exam', '单元练习', '["外研版","四年级","下册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["Unit 1 重点句型"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-020-014');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-020-014', 'en-kp-020-05', 'en-q-020-014', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-020-014');
