INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-021-002', 'en-repo-021', '2', 'I feel sad, ___ I can''t take part in the Beijing opera show.（我感到伤心，因为我不能参加京剧表演了。）', 'FillBlank', '{"id":"en-q-021-002","title":"I feel sad, ___ I can''t take part in the Beijing opera show.（我感到伤心，因为我不能参加京剧表演了。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["because 引导原因状语从句"],"examAnalysis":"考查 because 引导原因状语从句（Unit 2语法点4）。''我伤心''的原因是''不能参加京剧表演''，用 because（因为）连接。because 用来解释原因，相当于回答 Why…?。","examCorrectAnswer":"because","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","下册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["because 引导原因状语从句"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-021-002');
