INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-021-003', 'en-repo-021', '3', 'Is she ___? Yes, she is.（她在咳嗽吗？是的，她在咳嗽。）', 'FillBlank', '{"id":"en-q-021-003","title":"Is she ___? Yes, she is.（她在咳嗽吗？是的，她在咳嗽。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["现在进行时 be + 动词-ing"],"examAnalysis":"考查现在进行时 be + 动词-ing（Unit 2语法点2）。问句 Is she coughing?（她在咳嗽吗？）是现在进行时，动词 cough 要加 -ing 变为 coughing。结构：be 动词(am/is/are) + 动词-ing。","examCorrectAnswer":"coughing","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","下册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["现在进行时 be + 动词-ing"]', 'medium', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-021-003');
