INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-021-007', 'en-repo-021', '7', 'What ___ you happy? Playing with my friends makes me happy.（什么让你感到高兴？和朋友们一起玩让我高兴。）', 'FillBlank', '{"id":"en-q-021-007","title":"What ___ you happy? Playing with my friends makes me happy.（什么让你感到高兴？和朋友们一起玩让我高兴。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["Unit 2 重点句型"],"examAnalysis":"考查核心句 What makes you happy?（Unit 2重点句子）。''什么让你高兴？''用 What makes you happy?，主语 What 看作单数，动词 make 用三单形式 makes。答句 Playing with my friends makes me happy. 中也用 makes。","examCorrectAnswer":"makes","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","下册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["Unit 2 重点句型"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-021-007');
