INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-021-009', 'en-repo-021', '9', 'Listen! The baby is ___.', 'Radio', '{"id":"en-q-021-009","title":"Listen! The baby is ___.","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["现在进行时 be + 动词-ing"],"examAnalysis":"考查现在进行时 be + 动词-ing（Unit 2语法点2）。Listen!（听！）提示动作正在发生，用现在进行时 be + V-ing，cough→coughing。A项 cough 是原形；B项 coughs 是一般现在时三单；D项 is cough 结构错误，故C正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"coughing","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"is cough","attribute":{}},{"id":"c","title":"cough","attribute":{}},{"id":"d","title":"coughs","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","下册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["现在进行时 be + 动词-ing"]', 'medium', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-021-009');
