INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-021-010', 'en-repo-021', '10', 'You should ___ sorry to your friend.', 'Radio', '{"id":"en-q-021-010","title":"You should ___ sorry to your friend.","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["should + 动词原形表应该"],"examAnalysis":"考查 should + 动词原形（Unit 2语法点3）。should 是情态动词，后面必须接动词原形 say。B项 says 是三单，C项 saying 是现在分词，D项 said 是过去式，都不能跟在 should 后，故A正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"saying","attribute":{}},{"id":"b","title":"says","attribute":{}},{"id":"c","title":"said","attribute":{}},{"id":"d","title":"say","attribute":{"examCorrectAnswer":"d"}}]}', 'exam', '单元练习', '["外研版","四年级","下册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["should + 动词原形表应该"]', 'medium', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-021-010');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-021-010', 'en-kp-021-04', 'en-q-021-010', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-021-010');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-021-011', 'en-repo-021', '11', 'I am happy, ___ today is my birthday.', 'Radio', '{"id":"en-q-021-011","title":"I am happy, ___ today is my birthday.","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["because 引导原因状语从句"],"examAnalysis":"考查 because 表原因（Unit 2语法点4）。''我高兴''的原因是''今天是我生日''，用 because（因为）。B项 so（所以）表结果；C项 but（但是）表转折；D项 and（和）表并列，都不表原因，故A正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"and","attribute":{}},{"id":"b","title":"but","attribute":{}},{"id":"c","title":"so","attribute":{}},{"id":"d","title":"because","attribute":{"examCorrectAnswer":"d"}}]}', 'exam', '单元练习', '["外研版","四年级","下册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["because 引导原因状语从句"]', 'medium', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-021-011');
