INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-022-001', 'en-repo-022', '1', '— What are you ___? — I''m looking at their clothes.（— 你正在做什么？— 我正在看他们的衣服。）', 'FillBlank', '{"id":"en-q-022-001","title":"— What are you ___? — I''m looking at their clothes.（— 你正在做什么？— 我正在看他们的衣服。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["现在进行时 be + 动词-ing"],"examAnalysis":"考查现在进行时 What are you doing?（Unit 3语法点1）。''你正在做什么？''是 What are you doing?，do 的 -ing 形式是 doing。回答用 I''m + 动词-ing，如 I''m looking at their clothes.。","examCorrectAnswer":"doing","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","下册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["现在进行时 be + 动词-ing"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-022-001');
