INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-022-002', 'en-repo-022', '2', 'Don''t ___ about your clothes. Just go and dance.（别担心你的衣服，只管去跳舞就好。）', 'FillBlank', '{"id":"en-q-022-002","title":"Don''t ___ about your clothes. Just go and dance.（别担心你的衣服，只管去跳舞就好。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["否定祈使句 Don''t + 动词原形"],"examAnalysis":"考查否定祈使句 Don''t + 动词原形（Unit 3语法点3）。''不要担心''是 Don''t worry about…，Don''t 后接动词原形 worry。worry about 意为''担心……''。","examCorrectAnswer":"worry","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","下册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["否定祈使句 Don''t + 动词原形"]', 'medium', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-022-002');
