INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-024-014', 'en-repo-024', '14', '下面哪个句子正确表达''我们能环游世界吗？''？', 'Radio', '{"id":"en-q-024-014","title":"下面哪个句子正确表达''我们能环游世界吗？''？","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 5","section":"重点语法与句型","knowledgePoint":["Unit 5 重点句型"],"examAnalysis":"考查情态动词 Can 的一般疑问句（Unit 5重点句子）。''能……吗？''用 Can + 主语 + 动词原形…?，即 Can we travel…?。B项 Are 后不能接动词原形 travel；C项 Do 后应接原形而非 traveling；D项 Does 与主语 we 不搭配，故A正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Are we travel around the world?","attribute":{}},{"id":"b","title":"Can we travel around the world?","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"Does we travel around the world?","attribute":{}},{"id":"d","title":"Do we traveling around the world?","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","下册","Unit 5"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 5', '重点语法与句型', '["Unit 5 重点句型"]', 'medium', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-024-014');
