INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-024-015', 'en-repo-024', '15', 'Look! The baby bird ___ the tree.', 'Radio', '{"id":"en-q-024-015","title":"Look! The baby bird ___ the tree.","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 5","section":"重点语法与句型","knowledgePoint":["Unit 5 重点句型"],"examAnalysis":"考查核心句 It falls off the tree.（Unit 5重点句子）。主语 The baby bird 是三单，描述当下看到的情况用一般现在时，fall→falls。B项 fall 原形；C项 falling 不能单独作谓语；D项 fell 是过去式，故A正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"fell off","attribute":{}},{"id":"b","title":"fall off","attribute":{}},{"id":"c","title":"falling off","attribute":{}},{"id":"d","title":"falls off","attribute":{"examCorrectAnswer":"d"}}]}', 'exam', '单元练习', '["外研版","四年级","下册","Unit 5"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 5', '重点语法与句型', '["Unit 5 重点句型"]', 'medium', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-024-015');
