INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-025-008', 'en-repo-025', '8', '你想说''我正穿着一件T恤衫和一条短裤''，应说：___', 'Radio', '{"id":"en-q-025-008","title":"你想说''我正穿着一件T恤衫和一条短裤''，应说：___","type":"Radio","attribute":{"subject":"英语","difficulty":"easy","chapter":"Unit 6","section":"重点语法与句型","knowledgePoint":["现在进行时 be + 动词-ing 表穿着/正在做"],"examAnalysis":"考查现在进行时表穿着（Unit 6语法点1）。表示当前穿着用现在进行时 be + V-ing，I''m wearing…。B项一般现在时表习惯性动作；C项过去时；D项缺 be 动词，故A正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"I wore a T-shirt and shorts.","attribute":{}},{"id":"b","title":"I wear a T-shirt and shorts.","attribute":{}},{"id":"c","title":"I''m wearing a T-shirt and shorts.","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"I wearing a T-shirt and shorts.","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","下册","Unit 6"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 6', '重点语法与句型', '["现在进行时 be + 动词-ing 表穿着/正在做"]', 'easy', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-025-008');
