INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-026-002', 'en-repo-026', '2', 'You should ___ (have) some vegetables.（你应该吃些蔬菜。）', 'FillBlank', '{"id":"en-q-026-002","title":"You should ___ (have) some vegetables.（你应该吃些蔬菜。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"easy","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["should表示建议：You should+动词原形+其他；否定式shouldn''t=should not"],"examAnalysis":"考查 should 表示建议的用法（Unit1语法点2）。should 是情态动词，后面必须接动词原形，即 You should + 动词原形，故填 have。","examCorrectAnswer":"have","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["should表示建议：You should+动词原形+其他；否定式shouldn''t=should not"]', 'easy', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-026-002');
