INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-026-003', 'en-repo-026', '3', 'What ___ you eat for lunch?（你午餐吃什么？）', 'FillBlank', '{"id":"en-q-026-003","title":"What ___ you eat for lunch?（你午餐吃什么？）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"easy","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["询问饮食习惯：What do you eat+三餐? I eat+食物.；第三人称用What does+主语+eat+三"],"examAnalysis":"考查询问饮食习惯的疑问句（Unit1语法点3）。主语是第二人称 you，一般现在时疑问句要借助助动词 do：What do you eat + 三餐？故填 do。","examCorrectAnswer":"do","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["询问饮食习惯：What do you eat+三餐? I eat+食物.；第三人称用What does+主语+eat+三"]', 'easy', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-026-003');
