INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-026-009', 'en-repo-026', '9', '— I have a stomachache. — You ___ drink too much cola.', 'Radio', '{"id":"en-q-026-009","title":"— I have a stomachache. — You ___ drink too much cola.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["should表示建议：You should+动词原形+其他；否定式shouldn''t=should not"],"examAnalysis":"考查 should 表建议的否定式（Unit1语法点2）。胃疼时“不应该”喝太多可乐，应用 should 的否定式 shouldn''t（不应该）。A 项 should（应该）与语境相反；C 项 are、D 项 can 不能直接这样给出劝告，故 B 正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"should","attribute":{}},{"id":"b","title":"shouldn''t","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"are","attribute":{}},{"id":"d","title":"can","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["should表示建议：You should+动词原形+其他；否定式shouldn''t=should not"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-026-009');
