INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-026-010', 'en-repo-026', '10', '— What does Amy eat for breakfast? — She ___ bread and milk.', 'Radio', '{"id":"en-q-026-010","title":"— What does Amy eat for breakfast? — She ___ bread and milk.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["询问饮食习惯：What do you eat+三餐? I eat+食物.；第三人称用What does+主语+eat+三"],"examAnalysis":"考查第三人称单数的回答（Unit1语法点3）。问句用助动词 does，说明主语 Amy 是第三人称单数，回答中谓语动词要用三单形式 eats，故 A 正确。B 项 eat 用于非三单主语；C 项 eating 不能单独作谓语；D 项 ate 是过去式，与一般现在时问句不一致。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"eats","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"eat","attribute":{}},{"id":"c","title":"eating","attribute":{}},{"id":"d","title":"ate","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["询问饮食习惯：What do you eat+三餐? I eat+食物.；第三人称用What does+主语+eat+三"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-026-010');
