INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-032-001', 'en-repo-032', '1', 'I ___ four and Chenchen was ten months old.（我四岁，晨晨十个月大。）', 'FillBlank', '{"id":"en-q-032-001","title":"I ___ four and Chenchen was ten months old.（我四岁，晨晨十个月大。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["be动词一般过去式：am/is的过去式为was（单数主语），are的过去式为were（复数/第二人称主语）；否定形式为w"],"examAnalysis":"考查知识点：be动词一般过去式（本单元语法点1）。为什么填这个：主语I是单数第一人称，am/is的过去式为was，描述过去的年龄状态用一般过去时，故填was。相关规则：am/is的过去式是was（用于单数主语），are的过去式是were（用于复数/第二人称主语），否定式为wasn''t/weren''t。","examCorrectAnswer":"was","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["be动词一般过去式：am/is的过去式为was（单数主语），are的过去式为were（复数/第二人称主语）；否定形式为w"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-032-001');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-032-001', 'en-kp-032-01', 'en-q-032-001', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-032-001');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-032-002', 'en-repo-032', '2', 'They ___ at the summer camp last month.（他们上个月在夏令营。）', 'FillBlank', '{"id":"en-q-032-002","title":"They ___ at the summer camp last month.（他们上个月在夏令营。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["be动词一般过去式：am/is的过去式为was（单数主语），are的过去式为were（复数/第二人称主语）；否定形式为w"],"examAnalysis":"考查知识点：be动词一般过去式（本单元语法点1）。为什么填这个：主语They是复数，are的过去式为were，时间last month表过去，故填were。相关规则：复数主语/第二人称you搭配were，单数主语搭配was；例句They were at the summer camp yesterday.","examCorrectAnswer":"were","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["be动词一般过去式：am/is的过去式为was（单数主语），are的过去式为were（复数/第二人称主语）；否定形式为w"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-032-002');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-032-002', 'en-kp-032-01', 'en-q-032-002', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-032-002');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-032-003', 'en-repo-032', '3', 'At first, I couldn''t ___ (swim) at all.（起初我根本不会游泳。）', 'FillBlank', '{"id":"en-q-032-003","title":"At first, I couldn''t ___ (swim) at all.（起初我根本不会游泳。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["情态动词could的过去式用法：could是can的过去式，后接动词原形；否定形式为couldn''t。"],"examAnalysis":"考查知识点：情态动词could的过去式用法（本单元语法点2）。为什么填这个：couldn''t是could的否定式，could/couldn''t后面必须接动词原形，故填swim。相关规则：could是can的过去式，后接动词原形；否定形式为couldn''t，如She couldn''t ride a bike before.","examCorrectAnswer":"swim","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["情态动词could的过去式用法：could是can的过去式，后接动词原形；否定形式为couldn''t。"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-032-003');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-032-003', 'en-kp-032-02', 'en-q-032-003', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-032-003');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-032-004', 'en-repo-032', '4', 'We ___ (cook) lunch for ourselves yesterday.（我们昨天自己做了午饭。）', 'FillBlank', '{"id":"en-q-032-004","title":"We ___ (cook) lunch for ourselves yesterday.（我们昨天自己做了午饭。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["实义动词过去式：规则动词加-ed（clap→clapped, cook→cooked, practice→practic"],"examAnalysis":"考查知识点：实义动词过去式——规则动词加-ed（本单元语法点3）。为什么填这个：时间yesterday表过去，cook是规则动词，过去式直接加-ed变cooked。相关规则：规则动词过去式一般直接加-ed，如cook→cooked, help→helped, play→played。","examCorrectAnswer":"cooked","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["实义动词过去式：规则动词加-ed（clap→clapped, cook→cooked, practice→practic"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-032-004');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-032-004', 'en-kp-032-03', 'en-q-032-004', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-032-004');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-032-005', 'en-repo-032', '5', 'He ___ (win) the race yesterday.（他昨天赢了赛跑。）', 'FillBlank', '{"id":"en-q-032-005","title":"He ___ (win) the race yesterday.（他昨天赢了赛跑。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["实义动词过去式：规则动词加-ed（clap→clapped, cook→cooked, practice→practic"],"examAnalysis":"考查知识点：实义动词过去式——不规则动词（本单元语法点3）。为什么填这个：win是不规则动词，过去式不是加-ed，而是变为won，不能写成winned。相关规则：不规则动词需特殊记忆，如win→won, learn→learnt, grow→grew。","examCorrectAnswer":"won","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["实义动词过去式：规则动词加-ed（clap→clapped, cook→cooked, practice→practic"]', 'medium', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-032-005');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-032-005', 'en-kp-032-03', 'en-q-032-005', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-032-005');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-032-006', 'en-repo-032', '6', '___ first, I was very nervous and tired.（起初，我非常紧张和疲惫。）', 'FillBlank', '{"id":"en-q-032-006","title":"___ first, I was very nervous and tired.（起初，我非常紧张和疲惫。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["时间逻辑短语At first...By the end of...：At first接过去初期状态/动作，By the "],"examAnalysis":"考查知识点：时间逻辑短语At first...（本单元语法点4）。为什么填这个：At first是固定搭配，意为''起初、一开始''，句首大写，后接过去初期的状态，故填At。相关规则：At first接过去初期状态/动作，与By the end of...对比使用，均用一般过去时。","examCorrectAnswer":"At","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["时间逻辑短语At first...By the end of...：At first接过去初期状态/动作，By the "]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-032-006');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-032-006', 'en-kp-032-04', 'en-q-032-006', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-032-006');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-032-007', 'en-repo-032', '7', 'By the ___ of the camp, I got much better.（到夏令营结束时，我好多了。）', 'FillBlank', '{"id":"en-q-032-007","title":"By the ___ of the camp, I got much better.（到夏令营结束时，我好多了。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["时间逻辑短语At first...By the end of...：At first接过去初期状态/动作，By the "],"examAnalysis":"考查知识点：时间逻辑短语By the end of...（本单元语法点4）。为什么填这个：By the end of是固定搭配，意为''到……结束时''，后接时间/事件，表过去最终的变化，故填end。相关规则：By the end of+时间/事件用一般过去时，与At first形成前后对比。","examCorrectAnswer":"end","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["时间逻辑短语At first...By the end of...：At first接过去初期状态/动作，By the "]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-032-007');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-032-007', 'en-kp-032-04', 'en-q-032-007', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-032-007');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-032-008', 'en-repo-032', '8', '— How old ___ you then? — I ___ four.', 'Radio', '{"id":"en-q-032-008","title":"— How old ___ you then? — I ___ four.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["be动词一般过去式：am/is的过去式为was（单数主语），are的过去式为were（复数/第二人称主语）；否定形式为w"],"examAnalysis":"考查知识点：be动词一般过去式（本单元语法点1）。为什么选A：问句主语you搭配were，答句主语I搭配was，时间then表过去，故选A。错误项：B项was与you、were与I主谓搭配颠倒；C项are/am是现在时，与then不符；D项is不能与you/I搭配。相关规则：you/复数用were，I/he/she/单数用was。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"were; was","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"was; were","attribute":{}},{"id":"c","title":"are; am","attribute":{}},{"id":"d","title":"is; is","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["be动词一般过去式：am/is的过去式为was（单数主语），are的过去式为were（复数/第二人称主语）；否定形式为w"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-032-008');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-032-008', 'en-kp-032-01', 'en-q-032-008', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-032-008');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-032-009', 'en-repo-032', '9', 'He ___ not a good player.（他不是一个好运动员。）', 'Radio', '{"id":"en-q-032-009","title":"He ___ not a good player.（他不是一个好运动员。）","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["be动词一般过去式：am/is的过去式为was（单数主语），are的过去式为were（复数/第二人称主语）；否定形式为w"],"examAnalysis":"考查知识点：be动词一般过去式否定（本单元语法点1）。为什么选B：主语He是单数，描述过去状态用was，was not=wasn''t，故选B。错误项：A项is是现在时；C项were只用于复数/you；D项are是现在时复数。相关规则：单数主语过去状态用was，否定式was not。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"is","attribute":{}},{"id":"b","title":"were","attribute":{}},{"id":"c","title":"are","attribute":{}},{"id":"d","title":"was","attribute":{"examCorrectAnswer":"d"}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["be动词一般过去式：am/is的过去式为was（单数主语），are的过去式为were（复数/第二人称主语）；否定形式为w"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-032-009');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-032-009', 'en-kp-032-01', 'en-q-032-009', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-032-009');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-032-010', 'en-repo-032', '10', 'She couldn''t ___ a bike before.（她以前不会骑自行车。）', 'Radio', '{"id":"en-q-032-010","title":"She couldn''t ___ a bike before.（她以前不会骑自行车。）","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["情态动词could的过去式用法：could是can的过去式，后接动词原形；否定形式为couldn''t。"],"examAnalysis":"考查知识点：couldn''t后接动词原形（本单元语法点2）。为什么选C：couldn''t后必须接动词原形ride。错误项：A项rides是三单形式；B项rode是过去式，情态动词后不用过去式；D项riding是现在分词，不能单独跟在couldn''t后。相关规则：can/could及其否定式后一律接动词原形。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"rides","attribute":{}},{"id":"b","title":"rode","attribute":{}},{"id":"c","title":"ride","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"riding","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["情态动词could的过去式用法：could是can的过去式，后接动词原形；否定形式为couldn''t。"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-032-010');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-032-010', 'en-kp-032-02', 'en-q-032-010', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-032-010');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-032-011', 'en-repo-032', '11', 'We ___ lunch for ourselves yesterday.', 'Radio', '{"id":"en-q-032-011","title":"We ___ lunch for ourselves yesterday.","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["实义动词过去式：规则动词加-ed（clap→clapped, cook→cooked, practice→practic"],"examAnalysis":"考查知识点：规则动词过去式（本单元语法点3）。为什么选C：yesterday表过去，cook的过去式cooked。错误项：A项cook是原形；B项cooks是一般现在时三单；D项cooking是现在分词，不能单独作谓语。相关规则：规则动词一般直接加-ed构成过去式。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"cook","attribute":{}},{"id":"b","title":"cooks","attribute":{}},{"id":"c","title":"cooked","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"cooking","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["实义动词过去式：规则动词加-ed（clap→clapped, cook→cooked, practice→practic"]', 'medium', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-032-011');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-032-011', 'en-kp-032-03', 'en-q-032-011', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-032-011');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-032-012', 'en-repo-032', '12', 'The boy ___ the game yesterday.', 'Radio', '{"id":"en-q-032-012","title":"The boy ___ the game yesterday.","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["实义动词过去式：规则动词加-ed（clap→clapped, cook→cooked, practice→practic"],"examAnalysis":"考查知识点：不规则动词过去式win→won（本单元语法点3）。为什么选C：win的过去式是不规则变化won。错误项：A项win是原形；B项winned是错误拼写，win不是规则动词；D项wins是现在时三单。相关规则：win→won，需特殊记忆，不能加-ed。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"win","attribute":{}},{"id":"b","title":"winned","attribute":{}},{"id":"c","title":"won","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"wins","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["实义动词过去式：规则动词加-ed（clap→clapped, cook→cooked, practice→practic"]', 'medium', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-032-012');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-032-012', 'en-kp-032-03', 'en-q-032-012', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-032-012');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-032-013', 'en-repo-032', '13', '___ the end of the party, we sang a song together.', 'Radio', '{"id":"en-q-032-013","title":"___ the end of the party, we sang a song together.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["时间逻辑短语At first...By the end of...：At first接过去初期状态/动作，By the "],"examAnalysis":"考查知识点：By the end of固定搭配（本单元语法点4）。为什么选B：By the end of意为''到……结束时''，符合句意。错误项：A项At first才是''起初''，不与the end of这样搭配；C项In the end可单独用但不接of；D项On不构成此搭配。相关规则：By the end of+时间/事件，表最终变化，用一般过去时。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"At","attribute":{}},{"id":"b","title":"By","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"In","attribute":{}},{"id":"d","title":"On","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["时间逻辑短语At first...By the end of...：At first接过去初期状态/动作，By the "]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-032-013');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-032-013', 'en-kp-032-04', 'en-q-032-013', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-032-013');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-032-014', 'en-repo-032', '14', '— Could you swim three years ago? — ___. I couldn''t swim at all.', 'Radio', '{"id":"en-q-032-014","title":"— Could you swim three years ago? — ___. I couldn''t swim at all.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["情态动词could的过去式用法：could是can的过去式，后接动词原形；否定形式为couldn''t。"],"examAnalysis":"考查知识点：could一般疑问句的回答（本单元语法点2）。为什么选B：答语后句说''我根本不会游泳''，是否定回答，Could开头的否定回答用No, I couldn''t。错误项：A项Yes与后句矛盾；C项did不能回答could问句；D项don''t是现在时，时态与助动词均不符。相关规则：Could you...? 回答用Yes, I could./No, I couldn''t.","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Yes, I could.","attribute":{}},{"id":"b","title":"Yes, I did.","attribute":{}},{"id":"c","title":"No, I don''t.","attribute":{}},{"id":"d","title":"No, I couldn''t.","attribute":{"examCorrectAnswer":"d"}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["情态动词could的过去式用法：could是can的过去式，后接动词原形；否定形式为couldn''t。"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-032-014');
