INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-033-001', 'en-repo-033', '1', 'They ___ (hurry) up to the top of the hill yesterday.（他们昨天匆忙赶到山顶。）', 'FillBlank', '{"id":"en-q-033-001","title":"They ___ (hurry) up to the top of the hill yesterday.（他们昨天匆忙赶到山顶。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["一般过去时动词变化：规则动词加-ed（hurry→hurried, help→helped, push→pushed, "],"examAnalysis":"考查知识点：规则动词过去式——辅音+y变i加-ed（本单元语法点1）。为什么填这个：hurry以''辅音字母+y''结尾，过去式变y为i再加-ed，即hurried。相关规则：hurry→hurried，类似study→studied；例句They hurried up to the top of the hill.","examCorrectAnswer":"hurried","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["一般过去时动词变化：规则动词加-ed（hurry→hurried, help→helped, push→pushed, "]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-033-001');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-033-001', 'en-kp-033-01', 'en-q-033-001', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-033-001');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-033-002', 'en-repo-033', '2', 'He ___ (see) some cans and picked them up.（他看到一些罐子，把它们捡了起来。）', 'FillBlank', '{"id":"en-q-033-002","title":"He ___ (see) some cans and picked them up.（他看到一些罐子，把它们捡了起来。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["一般过去时动词变化：规则动词加-ed（hurry→hurried, help→helped, push→pushed, "],"examAnalysis":"考查知识点：不规则动词过去式see→saw（本单元语法点1）。为什么填这个：see是不规则动词，过去式为saw，不能加-ed。相关规则：不规则动词需特殊记忆，如see→saw, go→went, give→gave。","examCorrectAnswer":"saw","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["一般过去时动词变化：规则动词加-ed（hurry→hurried, help→helped, push→pushed, "]', 'medium', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-033-002');
