INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-033-003', 'en-repo-033', '3', 'He didn''t ___ (hurry) to the top of the hill.（他没有匆忙赶到山顶。）', 'FillBlank', '{"id":"en-q-033-003","title":"He didn''t ___ (hurry) to the top of the hill.（他没有匆忙赶到山顶。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["一般过去时句型结构：陈述句（主语+动词过去式+其他）；否定句（主语+didn''t+动词原形+其他）；疑问句（Did+主语"],"examAnalysis":"考查知识点：一般过去时否定句didn''t+动词原形（本单元语法点2）。为什么填这个：否定句中didn''t后必须接动词原形hurry，不能用过去式。相关规则：主语+didn''t+动词原形+其他，如He didn''t hurry to the top.","examCorrectAnswer":"hurry","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["一般过去时句型结构：陈述句（主语+动词过去式+其他）；否定句（主语+didn''t+动词原形+其他）；疑问句（Did+主语"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-033-003');
