INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-033-005', 'en-repo-033', '5', 'She helped me ___ (carry) the heavy bag.（她帮我搬重包。）', 'FillBlank', '{"id":"en-q-033-005","title":"She helped me ___ (carry) the heavy bag.（她帮我搬重包。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["help sb (to) do sth句型：主语+helped+某人+动词原形+其他，help后接的动词必须用原形（to"],"examAnalysis":"考查知识点：help sb (to) do sth句型（本单元语法点3）。为什么填这个：help后接的动词用原形（to可省略），故填carry。相关规则：help sb (to) do sth，help后动词必须用原形，如She helped me (to) carry the heavy bag.","examCorrectAnswer":"carry","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["help sb (to) do sth句型：主语+helped+某人+动词原形+其他，help后接的动词必须用原形（to"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-033-005');
