INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-033-007', 'en-repo-033', '7', 'Can I ___ you carry the cart?（我可以帮你推手推车吗？）', 'FillBlank', '{"id":"en-q-033-007","title":"Can I ___ you carry the cart?（我可以帮你推手推车吗？）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["can的用法：表能力（主语+can/can''t+动词原形）；表请求/建议（Can I+动词原形...? 回答用Yes,p"],"examAnalysis":"考查知识点：Can I...?表请求（本单元语法点4）及help sb do sth（语法点3）。为什么填这个：Can I后接动词原形help，构成请求句型。相关规则：Can I+动词原形...? 表请求/建议，回答用Yes,please./No,thanks.","examCorrectAnswer":"help","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["can的用法：表能力（主语+can/can''t+动词原形）；表请求/建议（Can I+动词原形...? 回答用Yes,p"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-033-007');
