INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-033-010', 'en-repo-033', '10', '— Did you help the elderly cross the street? — ___', 'Radio', '{"id":"en-q-033-010","title":"— Did you help the elderly cross the street? — ___","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["一般过去时句型结构：陈述句（主语+动词过去式+其他）；否定句（主语+didn''t+动词原形+其他）；疑问句（Did+主语"],"examAnalysis":"考查知识点：Did疑问句的回答（本单元语法点2）。为什么选A：Did开头的一般疑问句，肯定回答用Yes,主语+did。错误项：B项do是现在时助动词；C项No后应搭配didn''t，前后矛盾；D项was是be动词，不回答did问句。相关规则：Yes,...did./No,...didn''t.","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Yes, I did.","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"Yes, I do.","attribute":{}},{"id":"c","title":"No, I did.","attribute":{}},{"id":"d","title":"Yes, I was.","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["一般过去时句型结构：陈述句（主语+动词过去式+其他）；否定句（主语+didn''t+动词原形+其他）；疑问句（Did+主语"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-033-010');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-033-010', 'en-kp-033-02', 'en-q-033-010', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-033-010');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-033-011', 'en-repo-033', '11', 'She helped me ___ the heavy bag.', 'Radio', '{"id":"en-q-033-011","title":"She helped me ___ the heavy bag.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["help sb (to) do sth句型：主语+helped+某人+动词原形+其他，help后接的动词必须用原形（to"],"examAnalysis":"考查知识点：help sb (to) do sth（本单元语法点3）。为什么选D：help后接动词原形carry。错误项：A项carrying、B项carried、C项carries都不能直接跟在help me后作宾补。相关规则：help sb (to) do sth，动词用原形，to可省略。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"carrying","attribute":{}},{"id":"b","title":"carried","attribute":{}},{"id":"c","title":"carries","attribute":{}},{"id":"d","title":"carry","attribute":{"examCorrectAnswer":"d"}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["help sb (to) do sth句型：主语+helped+某人+动词原形+其他，help后接的动词必须用原形（to"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-033-011');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-033-011', 'en-kp-033-03', 'en-q-033-011', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-033-011');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-033-012', 'en-repo-033', '12', '— Can I help you carry the cart? — ___', 'Radio', '{"id":"en-q-033-012","title":"— Can I help you carry the cart? — ___","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["can的用法：表能力（主语+can/can''t+动词原形）；表请求/建议（Can I+动词原形...? 回答用Yes,p"],"examAnalysis":"考查知识点：Can I...?表请求的回答（本单元语法点4）。为什么选A：Can I help you?是主动提供帮助，接受用Yes,please.。错误项：B项Yes,I can.回答的是Can you...?；C项No,I don''t.时态/助动词不符；D项You''re welcome.用于回应感谢，不回应请求。相关规则：提供帮助的请求用Yes,please./No,thanks.回答。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Yes, please.","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"Yes, I can.","attribute":{}},{"id":"c","title":"No, I don''t.","attribute":{}},{"id":"d","title":"You''re welcome.","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["can的用法：表能力（主语+can/can''t+动词原形）；表请求/建议（Can I+动词原形...? 回答用Yes,p"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-033-012');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-033-012', 'en-kp-033-04', 'en-q-033-012', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-033-012');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-033-013', 'en-repo-033', '13', 'Mum ___ me a new book yesterday.', 'Radio', '{"id":"en-q-033-013","title":"Mum ___ me a new book yesterday.","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["一般过去时动词变化：规则动词加-ed（hurry→hurried, help→helped, push→pushed, "],"examAnalysis":"考查知识点：不规则动词过去式give→gave（本单元语法点1）。为什么选B：yesterday表过去，give的过去式是gave。错误项：A项gived是错误拼写；C项gives是现在时三单；D项give是原形。相关规则：give→gave，不规则变化需记忆。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"gived","attribute":{}},{"id":"b","title":"gave","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"gives","attribute":{}},{"id":"d","title":"give","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["一般过去时动词变化：规则动词加-ed（hurry→hurried, help→helped, push→pushed, "]', 'medium', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-033-013');
