INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-034-010', 'en-repo-034', '10', '— Were there many books on the shelf? — ___', 'Radio', '{"id":"en-q-034-010","title":"— Were there many books on the shelf? — ___","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["there be句型一般过去时疑问句：Were there+名词复数+地点/时间？回答Yes,there were./N"],"examAnalysis":"考查知识点：Were there问句的回答（本单元语法点2）。为什么选D：many books是复数，Were there...?的肯定回答用Yes, there were。错误项：A、B项was/wasn''t用于单数；C项they不能用于there be句型回答。相关规则：复数用there were/weren''t回答。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Yes, there was.","attribute":{}},{"id":"b","title":"No, there wasn''t.","attribute":{}},{"id":"c","title":"Yes, they were.","attribute":{}},{"id":"d","title":"Yes, there were.","attribute":{"examCorrectAnswer":"d"}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["there be句型一般过去时疑问句：Were there+名词复数+地点/时间？回答Yes,there were./N"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-034-010');
