INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-034-011', 'en-repo-034', '11', '___ there a park near your home ten years ago?', 'Radio', '{"id":"en-q-034-011","title":"___ there a park near your home ten years ago?","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["there be句型一般过去时疑问句：Were there+名词复数+地点/时间？回答Yes,there were./N"],"examAnalysis":"考查知识点：there be过去时疑问句——单数用Was（本单元语法点2）。为什么选C：a park是单数，ten years ago表过去，用Was there。错误项：A项Were用于复数；B、D项Is/Are是现在时，与ten years ago不符。相关规则：单数名词用Was there...?","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Were","attribute":{}},{"id":"b","title":"Is","attribute":{}},{"id":"c","title":"Was","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"Are","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["there be句型一般过去时疑问句：Were there+名词复数+地点/时间？回答Yes,there were./N"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-034-011');
