INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-034-012', 'en-repo-034', '12', 'Last week, I ___ the street library.', 'Radio', '{"id":"en-q-034-012","title":"Last week, I ___ the street library.","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["一般过去时陈述句：描述过去发生的动作或存在的状态，谓语动词用过去式。时间状语有yesterday, last week,"],"examAnalysis":"考查知识点：一般过去时陈述句（本单元语法点3）。为什么选C：Last week表过去，visit用过去式visited。错误项：A项visit是原形；B项visits是现在时三单；D项visiting是现在分词。相关规则：过去时间状语谓语动词用过去式。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"visit","attribute":{}},{"id":"b","title":"visits","attribute":{}},{"id":"c","title":"visited","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"visiting","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["一般过去时陈述句：描述过去发生的动作或存在的状态，谓语动词用过去式。时间状语有yesterday, last week,"]', 'medium', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-034-012');
