INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-035-001', 'en-repo-035', '1', 'What ___ ancient people put in the dumplings?（古代人在饺子里包了什么？）', 'FillBlank', '{"id":"en-q-035-001","title":"What ___ ancient people put in the dumplings?（古代人在饺子里包了什么？）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 4","section":"重点语法与句型","knowledgePoint":["一般过去时特殊疑问句：对动作提问用 What/How/When+did+主语+动词原形？；对状态提问用 Why/How+"],"examAnalysis":"考查知识点：一般过去时特殊疑问句（本单元语法点1）。为什么填这个：对过去动作提问，用What+did+主语+动词原形，故填did。相关规则：What/How/When+did+主语+动词原形？did后接动词原形。","examCorrectAnswer":"did","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 4"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 4', '重点语法与句型', '["一般过去时特殊疑问句：对动作提问用 What/How/When+did+主语+动词原形？；对状态提问用 Why/How+"]', 'medium', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-035-001');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-035-001', 'en-kp-035-01', 'en-q-035-001', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-035-001');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-035-002', 'en-repo-035', '2', 'How ___ dumplings come to Xinjiang?（饺子是如何传到新疆的？）', 'FillBlank', '{"id":"en-q-035-002","title":"How ___ dumplings come to Xinjiang?（饺子是如何传到新疆的？）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 4","section":"重点语法与句型","knowledgePoint":["一般过去时特殊疑问句：对动作提问用 What/How/When+did+主语+动词原形？；对状态提问用 Why/How+"],"examAnalysis":"考查知识点：How引导的一般过去时特殊疑问句（本单元语法点1）。为什么填这个：对过去方式提问用How+did+主语+动词原形come。相关规则：How did+主语+动词原形？回答用过去时陈述句。","examCorrectAnswer":"did","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 4"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 4', '重点语法与句型', '["一般过去时特殊疑问句：对动作提问用 What/How/When+did+主语+动词原形？；对状态提问用 Why/How+"]', 'medium', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-035-002');
