INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-035-004', 'en-repo-035', '4', 'Pepys ___ (dig) a hole in his garden.（佩皮斯在他的花园里挖了一个洞。）', 'FillBlank', '{"id":"en-q-035-004","title":"Pepys ___ (dig) a hole in his garden.（佩皮斯在他的花园里挖了一个洞。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 4","section":"重点语法与句型","knowledgePoint":["一般过去时肯定句：be动词用主语+was/were+表语；实义动词用主语+动词过去式。不规则变化：go→went, do"],"examAnalysis":"考查知识点：不规则/重读闭音节动词过去式dig→dug（本单元语法点2、4）。为什么填这个：dig的过去式为dug。相关规则：dig→dug，不规则变化，不能写成digged。","examCorrectAnswer":"dug","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 4"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 4', '重点语法与句型', '["一般过去时肯定句：be动词用主语+was/were+表语；实义动词用主语+动词过去式。不规则变化：go→went, do"]', 'medium', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-035-004');
