INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-035-006', 'en-repo-035', '6', '___ Xinjiang an important trade centre? — Yes, it was.（新疆曾经是重要的贸易中心吗？——是的，它是。）', 'FillBlank', '{"id":"en-q-035-006","title":"___ Xinjiang an important trade centre? — Yes, it was.（新疆曾经是重要的贸易中心吗？——是的，它是。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 4","section":"重点语法与句型","knowledgePoint":["一般过去时一般疑问句：实义动词用 Did+主语+动词原形？回答Yes,...did./No,...didn''t.；be动"],"examAnalysis":"考查知识点：一般过去时一般疑问句——be动词用Was/Were（本单元语法点3）。为什么填这个：主语Xinjiang是单数，be动词一般疑问句用Was开头，答句it was呼应。相关规则：be动词直接用Was/Were+主语？回答Yes,...was/were.","examCorrectAnswer":"Was","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 4"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 4', '重点语法与句型', '["一般过去时一般疑问句：实义动词用 Did+主语+动词原形？回答Yes,...did./No,...didn''t.；be动"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-035-006');
