INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-035-015', 'en-repo-035', '15', 'She ___ history last month.', 'Radio', '{"id":"en-q-035-015","title":"She ___ history last month.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 4","section":"重点语法与句型","knowledgePoint":["实义动词过去式规则变化：直接加-ed（look→looked）；以e结尾加-d（like→liked）；辅音+y变i加-"],"examAnalysis":"考查知识点：规则动词过去式——辅音+y变i加-ed（本单元语法点4）。为什么选B：study以辅音+y结尾，变y为i加-ed为studied。错误项：A项studyed未变i；C项study原形；D项studies现在时三单。相关规则：辅音+y结尾动词变y为i再加-ed，如study→studied。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"studyed","attribute":{}},{"id":"b","title":"studied","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"study","attribute":{}},{"id":"d","title":"studies","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 4"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 4', '重点语法与句型', '["实义动词过去式规则变化：直接加-ed（look→looked）；以e结尾加-d（like→liked）；辅音+y变i加-"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-035-015');
