INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-036-001', 'en-repo-036', '1', 'What ___ he do?（他做了什么？）', 'FillBlank', '{"id":"en-q-036-001","title":"What ___ he do?（他做了什么？）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"easy","chapter":"Unit 5","section":"重点语法与句型","knowledgePoint":["一般过去时特殊疑问句：特殊疑问词+did+主语+动词原形+其他，did为助动词后接动词原形，答句用一般过去时陈述句。"],"examAnalysis":"考查知识点：一般过去时特殊疑问句（本单元语法点1）。为什么填这个：What+did+主语+动词原形do，故填did。相关规则：特殊疑问词+did+主语+动词原形+其他，答句用过去时陈述句。","examCorrectAnswer":"did","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 5"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 5', '重点语法与句型', '["一般过去时特殊疑问句：特殊疑问词+did+主语+动词原形+其他，did为助动词后接动词原形，答句用一般过去时陈述句。"]', 'easy', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-036-001');
