INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-036-007', 'en-repo-036', '7', 'The police ___ (find) the secret in the letter.（警察在信里发现了秘密。）', 'FillBlank', '{"id":"en-q-036-007","title":"The police ___ (find) the secret in the letter.（警察在信里发现了秘密。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 5","section":"重点语法与句型","knowledgePoint":["实义动词不规则过去式：steal→stole, find→found, come→came, take→took, di"],"examAnalysis":"考查知识点：不规则动词过去式find→found（本单元语法点2）。为什么填这个：find的过去式是不规则变化found。相关规则：find→found，主语任何人称形式不变。","examCorrectAnswer":"found","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 5"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 5', '重点语法与句型', '["实义动词不规则过去式：steal→stole, find→found, come→came, take→took, di"]', 'medium', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-036-007');
