INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-036-009', 'en-repo-036', '9', 'How ___ she solve the problem?', 'Radio', '{"id":"en-q-036-009","title":"How ___ she solve the problem?","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 5","section":"重点语法与句型","knowledgePoint":["一般过去时特殊疑问句：特殊疑问词+did+主语+动词原形+其他，did为助动词后接动词原形，答句用一般过去时陈述句。"],"examAnalysis":"考查知识点：How+did+主语+动词原形（本单元语法点1）。为什么选A：solve是实义动词原形，过去时疑问句用did。错误项：B、C项was/were后不接动词原形solve；D项does是现在时三单。相关规则：对过去动作方式提问用did。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"did","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"was","attribute":{}},{"id":"c","title":"were","attribute":{}},{"id":"d","title":"does","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 5"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 5', '重点语法与句型', '["一般过去时特殊疑问句：特殊疑问词+did+主语+动词原形+其他，did为助动词后接动词原形，答句用一般过去时陈述句。"]', 'medium', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-036-009');
