INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-037-001', 'en-repo-037', '1', 'We ___ (leave) Beijing in the morning.（我们早上离开北京。）', 'FillBlank', '{"id":"en-q-037-001","title":"We ___ (leave) Beijing in the morning.（我们早上离开北京。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 6","section":"重点语法与句型","knowledgePoint":["实义动词过去式：规则变化（work→worked, travel→travelled, relax→relaxed）；不"],"examAnalysis":"考查知识点：不规则动词过去式leave→left（本单元语法点2）。为什么填这个：描述过去行程，leave的过去式是不规则变化left。相关规则：leave→left，类似get→got, give→gave, become→became。","examCorrectAnswer":"left","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 6"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 6', '重点语法与句型', '["实义动词过去式：规则变化（work→worked, travel→travelled, relax→relaxed）；不"]', 'medium', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-037-001');
