INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-037-002', 'en-repo-037', '2', 'We got to Xi''an in time ___ lunch.（我们及时赶到西安吃午饭。）', 'FillBlank', '{"id":"en-q-037-002","title":"We got to Xi''an in time ___ lunch.（我们及时赶到西安吃午饭。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 6","section":"重点语法与句型","knowledgePoint":["数词表达：million（百万），数词+million+可数名词复数（如10 million trees）。介词短语表地"],"examAnalysis":"考查知识点：介词短语in time for lunch（本单元语法点4）。为什么填这个：in time for+名词是固定搭配，意为''及时赶上……''，故填for。相关规则：in time for lunch及时吃午饭；类似介词短语in the morning, on the way to school。","examCorrectAnswer":"for","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 6"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 6', '重点语法与句型', '["数词表达：million（百万），数词+million+可数名词复数（如10 million trees）。介词短语表地"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-037-002');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-037-002', 'en-kp-037-02', 'en-q-037-002', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-037-002');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-037-003', 'en-repo-037', '3', 'The streets of China ___ (be) full of bikes 30 years ago.（30年前中国的街道上满是自行车。）', 'FillBlank', '{"id":"en-q-037-003","title":"The streets of China ___ (be) full of bikes 30 years ago.（30年前中国的街道上满是自行车。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 6","section":"重点语法与句型","knowledgePoint":["一般过去时与一般现在时对比：用was/were描述过去状态，用is/are/looks描述现在状态，通过系动词时态变化体"],"examAnalysis":"考查知识点：一般过去时描述过去状态——be动词用were（本单元语法点1、3）。为什么填这个：streets是复数，30 years ago表过去，用were。相关规则：过去状态用was/were+表语；复数主语用were。","examCorrectAnswer":"were","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 6"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 6', '重点语法与句型', '["一般过去时与一般现在时对比：用was/were描述过去状态，用is/are/looks描述现在状态，通过系动词时态变化体"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-037-003');
