INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-037-011', 'en-repo-037', '11', 'After 22 years, the mountains ___ a green world with over 10 million trees.', 'Radio', '{"id":"en-q-037-011","title":"After 22 years, the mountains ___ a green world with over 10 million trees.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 6","section":"重点语法与句型","knowledgePoint":["实义动词过去式：规则变化（work→worked, travel→travelled, relax→relaxed）；不"],"examAnalysis":"考查知识点：become的过去式（本单元语法点2）。为什么选C：After 22 years表过去完成的变化，become过去式became。错误项：A项become原形；B项becomed错误拼写；D项becomes现在时三单。相关规则：become→became。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"become","attribute":{}},{"id":"b","title":"becomed","attribute":{}},{"id":"c","title":"became","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"becomes","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 6"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 6', '重点语法与句型', '["实义动词过去式：规则变化（work→worked, travel→travelled, relax→relaxed）；不"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-037-011');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-037-011', 'en-kp-037-01', 'en-q-037-011', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-037-011');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-037-012', 'en-repo-037', '12', 'The teahouse ___ quiet yesterday, and it ___ still quiet today.', 'Radio', '{"id":"en-q-037-012","title":"The teahouse ___ quiet yesterday, and it ___ still quiet today.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 6","section":"重点语法与句型","knowledgePoint":["系动词时态变化：was/were用于过去，is/are/looks用于现在，后接形容词或介词短语表状态。"],"examAnalysis":"考查知识点：系动词时态变化（本单元语法点3）。为什么选A：yesterday用过去时was，today用现在时is，主语the teahouse是单数。错误项：B项时态颠倒；C项were与单数主语不符；D项后空仍用过去时，未体现现在。相关规则：was/were用于过去，is/are/looks用于现在，后接形容词。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"was; is","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"is; was","attribute":{}},{"id":"c","title":"were; is","attribute":{}},{"id":"d","title":"was; was","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 6"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 6', '重点语法与句型', '["系动词时态变化：was/were用于过去，is/are/looks用于现在，后接形容词或介词短语表状态。"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-037-012');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-037-012', 'en-kp-037-04', 'en-q-037-012', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-037-012');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-037-013', 'en-repo-037', '13', 'Over ten ___ trees grew on the mountain.', 'Radio', '{"id":"en-q-037-013","title":"Over ten ___ trees grew on the mountain.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 6","section":"重点语法与句型","knowledgePoint":["数词表达：million（百万），数词+million+可数名词复数（如10 million trees）。介词短语表地"],"examAnalysis":"考查知识点：数词million的用法（本单元语法点4）。为什么选C：数词+million+可数名词复数，million不加s，如10 million trees。错误项：A项millions前有具体数词ten时不加s；B项million of搭配错误；D项millions of表泛指''数百万''，不与具体数字ten连用。相关规则：具体数字+million+复数名词。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"millions","attribute":{}},{"id":"b","title":"million of","attribute":{}},{"id":"c","title":"million","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"millions of","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 6"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 6', '重点语法与句型', '["数词表达：million（百万），数词+million+可数名词复数（如10 million trees）。介词短语表地"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-037-013');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-037-013', 'en-kp-037-02', 'en-q-037-013', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-037-013');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-037-014', 'en-repo-037', '14', 'We left Beijing ___ the morning and got to Xi''an.', 'Radio', '{"id":"en-q-037-014","title":"We left Beijing ___ the morning and got to Xi''an.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 6","section":"重点语法与句型","knowledgePoint":["数词表达：million（百万），数词+million+可数名词复数（如10 million trees）。介词短语表地"],"examAnalysis":"考查知识点：介词短语in the morning（本单元语法点4）。为什么选A：in the morning是固定搭配，意为''在早上''。错误项：B项on用于具体某天；C项at用于具体时刻；D项for不与morning这样搭配。相关规则：in the morning, on the way to school等介词短语表时间/地点。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"in","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"on","attribute":{}},{"id":"c","title":"at","attribute":{}},{"id":"d","title":"for","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 6"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 6', '重点语法与句型', '["数词表达：million（百万），数词+million+可数名词复数（如10 million trees）。介词短语表地"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-037-014');
