INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-038-005', 'en-repo-038', '5', 'I''ll save my money ___ the right things from now on.（从现在起，我要把钱存起来用在该用的地方。）', 'FillBlank', '{"id":"en-q-038-005","title":"I''ll save my money ___ the right things from now on.（从现在起，我要把钱存起来用在该用的地方。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["动词短语：save money存钱；spend money on sth在某物上花钱；come true实现；turn."],"examAnalysis":"考查动词短语save money for（Unit 1语法点3）。save money for sth意为''为某事物存钱''，from now on意为''从现在起''。原句为I''ll save my money for the right things from now on.，故填for。注意区别spend money on sth（在某物上花钱）。","examCorrectAnswer":"for","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["动词短语：save money存钱；spend money on sth在某物上花钱；come true实现；turn."]', 'hard', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-038-005');
