INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-038-006', 'en-repo-038', '6', 'He wants to ___ the story into a film.（他想把故事变成电影。）', 'FillBlank', '{"id":"en-q-038-006","title":"He wants to ___ the story into a film.（他想把故事变成电影。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["动词短语：save money存钱；spend money on sth在某物上花钱；come true实现；turn."],"examAnalysis":"考查动词短语turn...into...（Unit 1语法点3）。turn...into...意为''把……变成……''，want to后接动词原形，故填turn。整句：He wants to turn the story into a film.。","examCorrectAnswer":"turn","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["动词短语：save money存钱；spend money on sth在某物上花钱；come true实现；turn."]', 'hard', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-038-006');
