INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-038-008', 'en-repo-038', '8', '— How much ___ the pen? — It''s 10 yuan.', 'Radio', '{"id":"en-q-038-008","title":"— How much ___ the pen? — It''s 10 yuan.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["how much引导特殊疑问句询问价格：How much + is + 单数/不可数名词？回答用It''s + 价格；Ho"],"examAnalysis":"考查how much + is + 单数名词询问价格（Unit 1语法点1）。pen是单数名词，用is：How much is the pen?。B项are用于复数名词（How much are…?），C项am只用于I，D项do不能与how much直接搭配询问价格，故A正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"is","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"are","attribute":{}},{"id":"c","title":"am","attribute":{}},{"id":"d","title":"do","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["how much引导特殊疑问句询问价格：How much + is + 单数/不可数名词？回答用It''s + 价格；Ho"]', 'hard', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-038-008');
