INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-038-009', 'en-repo-038', '9', '— How much are the shoes? — ___ 200 yuan.', 'Radio', '{"id":"en-q-038-009","title":"— How much are the shoes? — ___ 200 yuan.","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["how much引导特殊疑问句询问价格：How much + is + 单数/不可数名词？回答用It''s + 价格；Ho"],"examAnalysis":"考查how much复数问句的应答（Unit 1语法点1）。问句How much are the shoes?中shoes是复数，回答用They''re + 价格（它们是……元），故B正确。A项It''s用于单数/不可数名词的回答，C、D项人称不符。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"It''s","attribute":{}},{"id":"b","title":"They''re","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"He''s","attribute":{}},{"id":"d","title":"I''m","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["how much引导特殊疑问句询问价格：How much + is + 单数/不可数名词？回答用It''s + 价格；Ho"]', 'medium', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-038-009');
