INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-038-012', 'en-repo-038', '12', '下面哪个短语的意思是''存钱''？', 'Radio', '{"id":"en-q-038-012","title":"下面哪个短语的意思是''存钱''？","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["动词短语：save money存钱；spend money on sth在某物上花钱；come true实现；turn."],"examAnalysis":"考查动词短语辨析（Unit 1语法点3）。save money是''存钱''；B项spend money是''花钱''，C项make money是''赚钱''，D项turn money不是固定搭配，故A正确。课文中I''ll save my money for the right things.（我要把钱存起来用在该用的地方）即用了save money。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"save money","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"spend money","attribute":{}},{"id":"c","title":"make money","attribute":{}},{"id":"d","title":"turn money","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["动词短语：save money存钱；spend money on sth在某物上花钱；come true实现；turn."]', 'hard', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-038-012');
