INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-038-014', 'en-repo-038', '14', 'Amy wants to ___ her story into a book.', 'Radio', '{"id":"en-q-038-014","title":"Amy wants to ___ her story into a book.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["动词短语：save money存钱；spend money on sth在某物上花钱；come true实现；turn."],"examAnalysis":"考查动词短语turn...into...（Unit 1语法点3）。turn...into...意为''把……变成……''：Amy wants to turn her story into a book.（艾米想把她的故事变成一本书）。B项make（制作）、C项get（得到）、D项do（做）都不能构成make/get/do...into...的固定搭配，故A正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"turn","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"make","attribute":{}},{"id":"c","title":"get","attribute":{}},{"id":"d","title":"do","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["动词短语：save money存钱；spend money on sth在某物上花钱；come true实现；turn."]', 'hard', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-038-014');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-038-014', 'en-kp-038-03', 'en-q-038-014', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-038-014');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-038-015', 'en-repo-038', '15', '— How much is the book? — ___', 'Radio', '{"id":"en-q-038-015","title":"— How much is the book? — ___","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["how much引导特殊疑问句询问价格：How much + is + 单数/不可数名词？回答用It''s + 价格；Ho"],"examAnalysis":"考查how much单数问句的应答（Unit 1语法点1）。问句How much is the book?中book是单数，回答用It''s + 价格，故A项It''s 15 yuan.正确。B项They''re用于复数回答，C项I''m 15.（我15岁）答非所问，D项Yes, it is.是be动词一般疑问句的应答，不用于特殊疑问句，排除。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"It''s 15 yuan.","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"They''re 15 yuan.","attribute":{}},{"id":"c","title":"I''m 15.","attribute":{}},{"id":"d","title":"Yes, it is.","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["how much引导特殊疑问句询问价格：How much + is + 单数/不可数名词？回答用It''s + 价格；Ho"]', 'hard', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-038-015');
