INSERT INTO t_knowledge_point (id, section_id, name, sort, grade, term, importance, content, image_url, is_deleted, create_at, create_by) SELECT 'en-kp-039-03', 'en-sec-039', '提出建议用"Why not + 动词原形…?"（为什么不……呢？）；表达观点用"In my opinion, + 句子.', '3', '六年级', '上册', 'key', '{"points":["提出建议用\"Why not + 动词原形…?\"（为什么不……呢？）；表达观点用\"In my opinion, + 句子."]}', NULL, '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point WHERE id = 'en-kp-039-03');
