INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-039-006', 'en-repo-039', '6', 'Why not just ___ (eat) it?（为什么不就把它吃了呢？）', 'FillBlank', '{"id":"en-q-039-006","title":"Why not just ___ (eat) it?（为什么不就把它吃了呢？）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"easy","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["提出建议用\"Why not + 动词原形…?\"（为什么不……呢？）；表达观点用\"In my opinion, + 句子."],"examAnalysis":"考查提出建议的句型（Unit 2语法点3）。Why not + 动词原形…? 意为''为什么不……呢？''，用来提建议，not后必须接动词原形，故填eat。","examCorrectAnswer":"eat","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["提出建议用\"Why not + 动词原形…?\"（为什么不……呢？）；表达观点用\"In my opinion, + 句子."]', 'easy', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-039-006');
