INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-039-008', 'en-repo-039', '8', 'Apples are ___ than sweet cakes.', 'Radio', '{"id":"en-q-039-008","title":"Apples are ___ than sweet cakes.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["形容词比较级：A + be动词 + 形容词比较级 + than + B，表示A比B更……。"],"examAnalysis":"考查形容词比较级句型（Unit 2语法点1）。句中有than，需用比较级；healthy的比较级为healthier，故选B。A项healthy是原级，不能与than连用；C项more healthier错误，比较级前不能再加more；D项healthiest是最高级，用于三者及以上。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"healthy","attribute":{}},{"id":"b","title":"healthier","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"more healthier","attribute":{}},{"id":"d","title":"healthiest","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["形容词比较级：A + be动词 + 形容词比较级 + than + B，表示A比B更……。"]', 'hard', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-039-008');
