INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-039-009', 'en-repo-039', '9', 'Which is the comparative (比较级) of "tall"?', 'Radio', '{"id":"en-q-039-009","title":"Which is the comparative (比较级) of \"tall\"?","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["形容词比较级规则变化：一般加-er；不发音e结尾加-r；重读闭音节双写尾字母加-er；辅音+y结尾变y为i加-er；多音"],"examAnalysis":"考查比较级规则变化（Unit 2语法点2）。tall是一般单音节词，直接加-er变taller，故选C。A项tallest是最高级；B项more tall错误，单音节词比较级不加more；D项tallier拼写错误。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"tallest","attribute":{}},{"id":"b","title":"more tall","attribute":{}},{"id":"c","title":"taller","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"tallier","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["形容词比较级规则变化：一般加-er；不发音e结尾加-r；重读闭音节双写尾字母加-er；辅音+y结尾变y为i加-er；多音"]', 'medium', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-039-009');
