INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-039-010', 'en-repo-039', '10', 'Which is the comparative (比较级) of "beautiful"?', 'Radio', '{"id":"en-q-039-010","title":"Which is the comparative (比较级) of \"beautiful\"?","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["形容词比较级规则变化：一般加-er；不发音e结尾加-r；重读闭音节双写尾字母加-er；辅音+y结尾变y为i加-er；多音"],"examAnalysis":"考查多音节词比较级（Unit 2语法点2）。beautiful是多音节词，比较级在前面加more，即more beautiful，故选B。A、D项把beautiful变成-er/-est是错误的；D项most beautiful是最高级，不是比较级。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"beautifuler","attribute":{}},{"id":"b","title":"more beautiful","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"beautifulest","attribute":{}},{"id":"d","title":"most beautiful","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["形容词比较级规则变化：一般加-er；不发音e结尾加-r；重读闭音节双写尾字母加-er；辅音+y结尾变y为i加-er；多音"]', 'hard', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-039-010');
