INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-039-012', 'en-repo-039', '12', 'Why not ___ to the park with us?', 'Radio', '{"id":"en-q-039-012","title":"Why not ___ to the park with us?","type":"Radio","attribute":{"subject":"英语","difficulty":"easy","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["提出建议用\"Why not + 动词原形…?\"（为什么不……呢？）；表达观点用\"In my opinion, + 句子."],"examAnalysis":"考查Why not提建议句型（Unit 2语法点3）。Why not后接动词原形，意为''为什么不……呢？''，故选C项go。A项going是动名词、B项goes是三单、D项went是过去式，都不能跟在Why not后面。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"going","attribute":{}},{"id":"b","title":"goes","attribute":{}},{"id":"c","title":"go","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"went","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["提出建议用\"Why not + 动词原形…?\"（为什么不……呢？）；表达观点用\"In my opinion, + 句子."]', 'easy', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-039-012');
