INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-039-013', 'en-repo-039', '13', '___, this book is very interesting.', 'Radio', '{"id":"en-q-039-013","title":"___, this book is very interesting.","type":"Radio","attribute":{"subject":"英语","difficulty":"easy","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["提出建议用\"Why not + 动词原形…?\"（为什么不……呢？）；表达观点用\"In my opinion, + 句子."],"examAnalysis":"考查表达观点的固定短语（Unit 2语法点3）。''在我看来''是In my opinion，介词用in，opinion用单数，故选B。A、C项介词错误；D项opinions用复数，习惯上用单数。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"On my opinion","attribute":{}},{"id":"b","title":"In my opinion","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"At my opinion","attribute":{}},{"id":"d","title":"In my opinions","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["提出建议用\"Why not + 动词原形…?\"（为什么不……呢？）；表达观点用\"In my opinion, + 句子."]', 'easy', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-039-013');
