INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-040-003', 'en-repo-040', '3', 'Xu Xiake is one of the ___ (famous) travellers in China.（徐霞客是中国最著名的旅行家之一。）', 'FillBlank', '{"id":"en-q-040-003","title":"Xu Xiake is one of the ___ (famous) travellers in China.（徐霞客是中国最著名的旅行家之一。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["\"one of + the + 形容词最高级 + 复数名词\"表示\"最……之一\"；询问\"有多……\"用\"How + 形容词 "],"examAnalysis":"考查''one of + the + 最高级 + 复数名词''结构（Unit 3语法点3）。famous是多音节词，最高级在前面加most，即most famous；该结构表示''最……之一''，后面名词travelers用复数。","examCorrectAnswer":"most famous","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["\"one of + the + 形容词最高级 + 复数名词\"表示\"最……之一\"；询问\"有多……\"用\"How + 形容词 "]', 'hard', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-040-003');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-040-003', 'en-kp-040-02', 'en-q-040-003', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-040-003');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-040-004', 'en-repo-040', '4', 'How ___ is it? It was 8848.86 metres high in 2020.（它有多高？2020年时高8848.86米。）', 'FillBlank', '{"id":"en-q-040-004","title":"How ___ is it? It was 8848.86 metres high in 2020.（它有多高？2020年时高8848.86米。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["\"one of + the + 形容词最高级 + 复数名词\"表示\"最……之一\"；询问\"有多……\"用\"How + 形容词 "],"examAnalysis":"考查询问''有多……''的句型（Unit 3语法点3）。How + 形容词 + be + 主语? 用来询问某物的程度，由答语8848.86 metres high可知问的是高度，故填high。","examCorrectAnswer":"high","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["\"one of + the + 形容词最高级 + 复数名词\"表示\"最……之一\"；询问\"有多……\"用\"How + 形容词 "]', 'medium', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-040-004');
