INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-040-005', 'en-repo-040', '5', 'This box is the ___ (big) of the three.（这个盒子是三个里面最大的。）', 'FillBlank', '{"id":"en-q-040-005","title":"This box is the ___ (big) of the three.（这个盒子是三个里面最大的。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["形容词最高级规则变化：一般加-est；不发音e结尾加-st；重读闭音节双写尾字母加-est；辅音+y结尾变y为i加-es"],"examAnalysis":"考查最高级规则变化（Unit 3语法点2）。of the three表示三者范围，用最高级；big是重读闭音节，双写g加-est变biggest，前面加the，故填biggest。","examCorrectAnswer":"biggest","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["形容词最高级规则变化：一般加-est；不发音e结尾加-st；重读闭音节双写尾字母加-est；辅音+y结尾变y为i加-es"]', 'medium', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-040-005');
