INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-040-009', 'en-repo-040', '9', 'Which is the superlative (最高级) of "beautiful"?', 'Radio', '{"id":"en-q-040-009","title":"Which is the superlative (最高级) of \"beautiful\"?","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["形容词最高级规则变化：一般加-est；不发音e结尾加-st；重读闭音节双写尾字母加-est；辅音+y结尾变y为i加-es"],"examAnalysis":"考查多音节词最高级（Unit 3语法点2）。beautiful是多音节词，最高级在前面加most，即most beautiful，故选D。A、C项拼写错误；B项more beautiful是比较级，不是最高级。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"beautifulest","attribute":{}},{"id":"b","title":"more beautiful","attribute":{}},{"id":"c","title":"beautifuler","attribute":{}},{"id":"d","title":"most beautiful","attribute":{"examCorrectAnswer":"d"}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["形容词最高级规则变化：一般加-est；不发音e结尾加-st；重读闭音节双写尾字母加-est；辅音+y结尾变y为i加-es"]', 'medium', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-040-009');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-040-009', 'en-kp-040-03', 'en-q-040-009', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-040-009');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-040-010', 'en-repo-040', '10', 'Which is the superlative (最高级) of "good"?', 'Radio', '{"id":"en-q-040-010","title":"Which is the superlative (最高级) of \"good\"?","type":"Radio","attribute":{"subject":"英语","difficulty":"easy","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["形容词最高级规则变化：一般加-est；不发音e结尾加-st；重读闭音节双写尾字母加-est；辅音+y结尾变y为i加-es"],"examAnalysis":"考查不规则最高级（Unit 3语法点2）。good的最高级是不规则变化best，故选A。B项goodest、D项most good都是错误形式；C项better是good的比较级，不是最高级。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"best","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"goodest","attribute":{}},{"id":"c","title":"better","attribute":{}},{"id":"d","title":"most good","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["形容词最高级规则变化：一般加-est；不发音e结尾加-st；重读闭音节双写尾字母加-est；辅音+y结尾变y为i加-es"]', 'easy', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-040-010');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-040-010', 'en-kp-040-03', 'en-q-040-010', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-040-010');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-040-011', 'en-repo-040', '11', 'Xu Xiake is one of the most famous ___ in China.', 'Radio', '{"id":"en-q-040-011","title":"Xu Xiake is one of the most famous ___ in China.","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["\"one of + the + 形容词最高级 + 复数名词\"表示\"最……之一\"；询问\"有多……\"用\"How + 形容词 "],"examAnalysis":"考查''one of + the + 最高级 + 复数名词''（Unit 3语法点3）。one of后面必须接可数名词复数，表示''……之一''，故traveler用复数travellers，选D。A项是单数；B项是所有格；C项复数形式错误。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"traveller","attribute":{}},{"id":"b","title":"traveller''s","attribute":{}},{"id":"c","title":"travelleres","attribute":{}},{"id":"d","title":"travellers","attribute":{"examCorrectAnswer":"d"}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["\"one of + the + 形容词最高级 + 复数名词\"表示\"最……之一\"；询问\"有多……\"用\"How + 形容词 "]', 'medium', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-040-011');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-040-011', 'en-kp-040-02', 'en-q-040-011', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-040-011');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-040-012', 'en-repo-040', '12', '— ___ is the river? — It''s about 6,000 kilometres long.', 'Radio', '{"id":"en-q-040-012","title":"— ___ is the river? — It''s about 6,000 kilometres long.","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["\"one of + the + 形容词最高级 + 复数名词\"表示\"最……之一\"；询问\"有多……\"用\"How + 形容词 "],"examAnalysis":"考查How + 形容词提问（Unit 3语法点3）。答语long表示长度，问句应问''有多长''，用How long，故选C。A项How high问高度；B项How old问年龄；D项How many问数量，均与答语不符。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"How high","attribute":{}},{"id":"b","title":"How old","attribute":{}},{"id":"c","title":"How long","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"How many","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["\"one of + the + 形容词最高级 + 复数名词\"表示\"最……之一\"；询问\"有多……\"用\"How + 形容词 "]', 'medium', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-040-012');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-040-012', 'en-kp-040-02', 'en-q-040-012', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-040-012');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-040-013', 'en-repo-040', '13', 'Tom is the ___ boy in our class.', 'Radio', '{"id":"en-q-040-013","title":"Tom is the ___ boy in our class.","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["形容词最高级：主语 + be动词 + the + 形容词最高级 + 范围(in/of...)，表示三者或以上中最……的，"],"examAnalysis":"考查最高级用法（Unit 3语法点1）。in our class表示范围，用最高级；tall直接加-est变tallest，前面有the，故选D。A项taller是比较级，不与in our class范围连用；B项tall是原级；C项most tall错误。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"taller","attribute":{}},{"id":"b","title":"tall","attribute":{}},{"id":"c","title":"most tall","attribute":{}},{"id":"d","title":"tallest","attribute":{"examCorrectAnswer":"d"}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["形容词最高级：主语 + be动词 + the + 形容词最高级 + 范围(in/of...)，表示三者或以上中最……的，"]', 'medium', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-040-013');
