INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-041-014', 'en-repo-041', '14', '— What is she doing? — She ___ a watering bottle for the plants.', 'Radio', '{"id":"en-q-041-014","title":"— What is she doing? — She ___ a watering bottle for the plants.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 4","section":"重点语法与句型","knowledgePoint":["现在进行时：主语 + am/is/are + 动词-ing形式，表示此时此刻正在进行的动作。"],"examAnalysis":"考查现在进行时第三人称单数（Unit 4语法点1/重点句子）。问句What is she doing?，回答用She is + doing；主语she是第三人称单数，be动词用is，make变making，故选D。A项缺be动词；B项are与she不搭配；C项缺be动词。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"make","attribute":{}},{"id":"b","title":"are making","attribute":{}},{"id":"c","title":"making","attribute":{}},{"id":"d","title":"is making","attribute":{"examCorrectAnswer":"d"}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 4"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 4', '重点语法与句型', '["现在进行时：主语 + am/is/are + 动词-ing形式，表示此时此刻正在进行的动作。"]', 'hard', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-041-014');
