INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-043-014', 'en-repo-043', '14', 'When in Rome, do ___ the Romans do.', 'Radio', '{"id":"en-q-043-014","title":"When in Rome, do ___ the Romans do.","type":"Radio","attribute":{"subject":"英语","difficulty":"easy","chapter":"Unit 6","section":"重点语法与句型","knowledgePoint":["Unit 6 重点句型"],"examAnalysis":"考查谚语固定搭配（Unit 6重点句子）。do as the Romans do意为''照罗马人那样做、入乡随俗''，as表示''按照、如同''，故选B。like作''像''讲时是介词，不引导从句。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"like","attribute":{}},{"id":"b","title":"as","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"and","attribute":{}},{"id":"d","title":"but","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 6"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 6', '重点语法与句型', '["Unit 6 重点句型"]', 'easy', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-043-014');
