INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-043-015', 'en-repo-043', '15', '感叹句中，如果形容词后面紧跟名词，用 ___ 引导。', 'Radio', '{"id":"en-q-043-015","title":"感叹句中，如果形容词后面紧跟名词，用 ___ 引导。","type":"Radio","attribute":{"subject":"英语","difficulty":"easy","chapter":"Unit 6","section":"重点语法与句型","knowledgePoint":["判断用what还是how：看形容词后是否紧跟名词——紧跟名词用what，否则用how。"],"examAnalysis":"考查what与how的判断规则（Unit 6语法点3）。判断用what还是how：看形容词后是否紧跟名词——紧跟名词用what（修饰名词），没有紧跟名词、直接是主语谓语用how（修饰形容词/副词），故选C。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"How","attribute":{}},{"id":"b","title":"When","attribute":{}},{"id":"c","title":"What","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"Where","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 6"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 6', '重点语法与句型', '["判断用what还是how：看形容词后是否紧跟名词——紧跟名词用what，否则用how。"]', 'easy', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-043-015');
