CREATE TABLE IF NOT EXISTS t_mall_order (
  id varchar(64) NOT NULL,
  student_id varchar(64) DEFAULT NULL COMMENT '学员ID(t_student.id)',
  student_no varchar(32) DEFAULT NULL COMMENT '学号(冗余快照)',
